function startRobotMatch(game,bet){const box=document.getElementById('match-status');if(!box)return;box.innerHTML=`<div class="robot-match"><span class="robot-icon">🤖</span><h2>مباراة ضد Robot</h2><p>الروبوت قوي، واحتمال فوزك في هذه المباراة <b>30%</b>.</p><button class="btn gold" onclick="confirmRobotMatch('${game}',${bet})">موافق · العب مع Robot</button></div>`;}
async function confirmRobotMatch(game,bet){const {error}=await db().rpc('start_robot_match',{p_game:game,p_bet:Number(bet)});if(error)return toast(error.message.includes('insufficient_coins')?'رصيدك لا يكفي لدفع الرهان':'تعذر بدء المباراة: '+error.message);profile.coins=Number(profile.coins)-Number(bet);location.hash=`robot/${encodeURIComponent(game)}/${bet}`;}
async function openUploadedGameLobby(file,title,gameKey,maxPlayers=2){
 const modal=document.createElement('div');modal.className='modal-backdrop';modal.innerHTML=`<div class="match-modal panel"><div class="panel-head"><div><span class="eyebrow">مطابقة أونلاين</span><h2>${title}</h2></div><button class="icon-btn" onclick="this.closest('.modal-backdrop').remove()">×</button></div><p class="empty">اختر قيمة الرهان. سيتم خصمها عند بدء اللعبة، والفائز يحصل على مجموع رهانات المباراة.</p><div class="bet-options">${[100,200,300,400,500].map(v=>`<button class="bet-option" data-bet="${v}" onclick="this.parentElement.querySelectorAll('.bet-option').forEach(x=>x.classList.remove('selected'));this.classList.add('selected')">${v}<small>كوينز</small></button>`).join('')}</div><div id="uploaded-match-status"><button class="btn gold full" onclick="startUploadedQueue('${file}','${title}','${gameKey}',${maxPlayers})">موافق · بدء المطابقة</button></div></div>`;document.body.appendChild(modal);modal.querySelector('.bet-option')?.click();}
async function startUploadedQueue(file,title,gameKey,maxPlayers){
 const modal=document.querySelector('.modal-backdrop'),box=document.getElementById('uploaded-match-status'),bet=Number(document.querySelector('.bet-option.selected')?.dataset.bet||100);if(!box)return;
 box.innerHTML=`<div class="match-queue"><h3>جاري البحث عن لاعبين حقيقيين</h3><div class="queue-counter" id="uploaded-counter">15</div><p>${escapeHtml(title)} · الرهان ${bet} كوينز · المطلوب ${maxPlayers} لاعبين</p><div class="queue-players">اتصال مباشر بقاعدة البيانات</div></div>`;
 const {data,error}=await db().rpc('join_game_match',{p_game_type:gameKey,p_bet_amount:bet});
 if(error){box.innerHTML=`<p class="empty">فشل بدء المطابقة: ${escapeHtml(error.message||'تحقق من إعدادات اللعبة')}</p>`;return;}
 const matchId=data?.match_id||data?.id;if(!matchId){box.innerHTML='<p class="empty">لم يتم إنشاء رقم المباراة.</p>';return;}
 let timer=null; const open=()=>{if(timer)clearInterval(timer);location.href=`games/${file}?match=${matchId}&bet=${bet}`;};
 if(data.status==='playing'){open();return;}
 let seconds=15;timer=setInterval(async()=>{seconds--;const el=document.getElementById('uploaded-counter');if(el)el.textContent=Math.max(seconds,0);if(seconds<=0){clearInterval(timer);if(gameKey==='Ahkam'){box.innerHTML='<p class="empty">تمت إضافة Robot للمقعد الناقص، جاري فتح المباراة...</p>';startUploadedRobot(file,title,bet,matchId);}else{box.innerHTML=`<div class="robot-offer"><p>لم يكتمل عدد اللاعبين. يمكن ملء المقاعد بالـBots.</p><button class="btn gold full" onclick="startUploadedRobot('${file}','${title}',${bet},'${matchId}')">بدء المباراة مع Bots</button></div>`;}}},1000);
 const watcher=setInterval(async()=>{const {data:m}=await db().from('game_matches').select('id,status').eq('id',matchId).maybeSingle();if(m?.status==='playing')open();},1000);
 setTimeout(()=>clearInterval(watcher),20000);
}
async function startUploadedRobot(file,title,bet,matchId=''){if(matchId){const {error}=await db().rpc('start_match_with_bots',{p_match:matchId});if(error)return toast('تعذر بدء المباراة: '+error.message);}location.href=`games/${file}?robot=1&match=${matchId||''}&bet=${bet}`;}
