async function games(){return page('الألعاب','home',`<div class="page-title"><span class="eyebrow">ألعاب أونلاين وفردية</span><h1>قاعة الألعاب</h1><p>الألعاب الأونلاين تبدأ باختيار الرهان والعداد والمطابقة. الروليت والسمك فردية.</p></div><div class="game-grid integrated-games">${INTEGRATED_GAMES.map((g,i)=>g[5]?`<a class="game-card integrated-game-card ${i<2?'featured':''}" href="#" onclick="event.preventDefault();openUploadedGameLobby('${g[0]}','${g[2]}','${g[6]}',${g[7]})"><div class="game-icon">${g[1]}</div><span class="pill">${g[4]}</span><h2>${g[2]}</h2><p>${g[3]}</p><span class="btn ${i<2?'gold':'ghost'} full">اختيار الرهان والمطابقة <i class="fa-solid fa-arrow-left"></i></span></a>`:`<a class="game-card integrated-game-card" href="games/${g[0]}"><div class="game-icon">${g[1]}</div><span class="pill">${g[4]}</span><h2>${g[2]}</h2><p>${g[3]}</p><span class="btn ghost full">فتح اللعبة <i class="fa-solid fa-arrow-left"></i></span></a>`).join('')}</div>`);}
let activeVoiceRoom=null;let voiceMuted=false,adminVoiceMuted=false;
let voicePeers={};
let voiceIceQueue={};
let voiceSignalPollTimer=null,voicePresencePollTimer=null,voiceSignalCursor=new Date(Date.now()-10000).toISOString(),voicePresenceCache=[];
function voiceSignal(channel,payload){if(!activeVoiceRoom)return Promise.resolve();return db().rpc('send_room_voice_signal',{p_room:activeVoiceRoom.roomId,p_receiver:payload.to||null,p_signal_type:payload.type,p_payload:payload}).then(({error})=>{if(error)console.warn('voice signal db failed',error);}).catch(e=>console.warn('voice signal failed',e));}
function stopVoicePolling(){if(voiceSignalPollTimer)clearInterval(voiceSignalPollTimer);if(voicePresencePollTimer)clearInterval(voicePresencePollTimer);voiceSignalPollTimer=null;voicePresencePollTimer=null;voicePresenceCache=[];}

let voiceVisualContext=null,voiceVisualSources=new Map(),voiceVisualFrame=null;
function setVoiceSpeaking(userId,level,kind='voice'){const roomId=activeVoiceRoom?.roomId;if(!roomId)return;const root=document.getElementById('voice-seats-'+roomId);if(!root)return;const seat=[...root.querySelectorAll('.voice-seat')].find(x=>x.dataset.userId===String(userId));if(seat){seat.classList.toggle(kind==='music'?'music-speaking':'voice-speaking',level>.035);seat.style.setProperty('--voice-level',String(Math.min(1,level)));}document.getElementById('voice-activity')?.style.setProperty('--voice-level',String(Math.min(1,level)));}
function stopVoiceVisual(id){const item=voiceVisualSources.get(id);if(item){try{item.source.disconnect();}catch(e){}voiceVisualSources.delete(id);}if(!voiceVisualSources.size&&voiceVisualFrame){cancelAnimationFrame(voiceVisualFrame);voiceVisualFrame=null;}}
function startVoiceVisual(id,stream,userId,kind='voice'){try{voiceVisualContext=voiceVisualContext||new (window.AudioContext||window.webkitAudioContext)();const analyser=voiceVisualContext.createAnalyser();analyser.fftSize=128;const source=stream instanceof HTMLMediaElement?voiceVisualContext.createMediaElementSource(stream):voiceVisualContext.createMediaStreamSource(stream);source.connect(analyser);if(stream instanceof HTMLMediaElement)analyser.connect(voiceVisualContext.destination);voiceVisualSources.set(id,{source,analyser,userId,kind,data:new Uint8Array(analyser.fftSize)});const tick=()=>{for(const item of voiceVisualSources.values()){item.analyser.getByteTimeDomainData(item.data);let sum=0;for(const v of item.data){const n=(v-128)/128;sum+=n*n;}setVoiceSpeaking(item.userId,Math.sqrt(sum/item.data.length),item.kind);}voiceVisualFrame=requestAnimationFrame(tick);};if(!voiceVisualFrame)tick();}catch(e){console.warn('voice visualizer unavailable',e);}}
function stopAllVoiceVisuals(){for(const id of [...voiceVisualSources.keys()])stopVoiceVisual(id);}
function closeVoicePeer(remoteId){const pc=voicePeers[remoteId];if(pc)pc.close();delete voicePeers[remoteId];delete voiceIceQueue[remoteId];document.getElementById('voice-audio-'+remoteId)?.remove();}
function createVoicePeer(roomId,remoteId,initiator){
  if(voicePeers[remoteId])return voicePeers[remoteId];
  const pc=new RTCPeerConnection({iceServers:[
    {urls:'stun:stun.l.google.com:19302'},
    {urls:'stun:stun.cloudflare.com:3478'},
    {urls:'turn:openrelay.metered.ca:80',username:'openrelayproject',credential:'openrelayproject'},
    {urls:'turns:openrelay.metered.ca:443?transport=tcp',username:'openrelayproject',credential:'openrelayproject'}
  ]});
  voicePeers[remoteId]=pc; voiceIceQueue[remoteId]=[];
  if(voiceStream)voiceStream.getTracks().forEach(t=>pc.addTrack(t,voiceStream));
  pc.onicecandidate=e=>{if(e.candidate&&activeVoiceRoom)voiceSignal(activeVoiceRoom.channel,{from:sessionUser.id,to:remoteId,type:'ice',candidate:e.candidate});};
  pc.onconnectionstatechange=()=>{if(['failed','closed','disconnected'].includes(pc.connectionState)){if(pc.connectionState==='failed')pc.restartIce?.();if(pc.connectionState==='closed')closeVoicePeer(remoteId);}};
  pc.ontrack=e=>{let a=document.getElementById('voice-audio-'+remoteId);if(!a){a=document.createElement('audio');a.id='voice-audio-'+remoteId;a.autoplay=true;a.playsInline=true;a.controls=false;document.body.appendChild(a);}a.srcObject=e.streams[0];startVoiceVisual('remote-'+remoteId,e.streams[0],remoteId,'voice');a.play?.().catch(()=>{});};
  if(initiator)pc.createOffer({offerToReceiveAudio:true}).then(o=>pc.setLocalDescription(o)).then(()=>activeVoiceRoom&&voiceSignal(activeVoiceRoom.channel,{from:sessionUser.id,to:remoteId,type:'offer',sdp:pc.localDescription})).catch(e=>console.warn('voice offer failed',e));
  return pc;
}
function voicePresenceEntries(){if(voicePresenceCache.length)return voicePresenceCache.filter(x=>x.user_id!==sessionUser.id);if(!activeVoiceRoom?.channel)return [];const state=activeVoiceRoom.channel.presenceState();return Object.values(state).flat().filter(x=>x.user_id&&x.user_id!==sessionUser.id);}
function voicePresenceMembers(){return voicePresenceEntries().map(x=>x.user_id);}
function connectVoicePeers(){voicePresenceMembers().forEach(remoteId=>{const initiator=String(sessionUser.id)>String(remoteId);createVoicePeer(activeVoiceRoom.roomId,remoteId,initiator);});}
async function toggleVoiceRoom(roomId){
  if(activeVoiceRoom?.roomId===roomId){
    try{await activeVoiceRoom.channel.untrack();}catch(e){}
    voiceStream?.getTracks().forEach(t=>t.stop());Object.keys(voicePeers).forEach(closeVoicePeer);voicePeers={};
    await db().rpc('remove_room_voice_presence',{p_room:roomId});await activeVoiceRoom.channel.unsubscribe();stopVoicePolling();activeVoiceRoom=null;voiceStream=null;voiceSlotState=null;sessionStorage.removeItem(VOICE_SESSION_KEY);stopAllVoiceVisuals();stopRoomMusic();toast('تم الخروج من المحادثة الصوتية');return false;
  }
  try{
    const savedVoice=JSON.parse(sessionStorage.getItem(VOICE_SESSION_KEY)||'null');if(savedVoice?.roomId===roomId){voiceSlotState={roomId,slot:Number(savedVoice.slot)||0};voiceMuted=!!savedVoice.muted;}
    voiceStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true},video:false});startVoiceVisual('local-mic',voiceStream,sessionUser.id,'voice');
    const channel=db().channel('voice-room-'+roomId,{config:{broadcast:{ack:true},presence:{key:sessionUser.id}}});
    activeVoiceRoom={roomId,channel};
    channel.on('presence',{event:'sync'},()=>{connectVoicePeers();refreshVoiceSeats(roomId);});
    channel.on('presence',{event:'join'},({key})=>{if(key&&key!==sessionUser.id)setTimeout(()=>{connectVoicePeers();refreshVoiceSeats(roomId);},100);});
    channel.on('presence',{event:'leave'},({key})=>{if(key){closeVoicePeer(key);refreshVoiceSeats(roomId);}});
    channel.on('broadcast',{event:'voice-admin'},async({payload})=>{if(!payload||payload.to!==sessionUser.id)return;if(payload.action==='mute'){adminVoiceMuted=true;voiceStream?.getAudioTracks().forEach(t=>t.enabled=false);document.querySelectorAll('.voice-mute-btn').forEach(b=>b.textContent='🔇 تم كتمك من مالك الغرفة');toast('قام مالك الغرفة بكتم الميكروفون');}else if(payload.action==='unmute'){adminVoiceMuted=false;voiceStream?.getAudioTracks().forEach(t=>t.enabled=!voiceMuted);document.querySelectorAll('.voice-mute-btn').forEach(b=>b.textContent=voiceMuted?'🔇 فتح الميكروفون':'🎙️ كتم الميكروفون');toast('تم فك كتم الميكروفون بواسطة مالك الغرفة');}else if(payload.action==='kick'){await toggleVoiceRoom(roomId);toast('تم إخراجك من المحادثة الصوتية بواسطة مالك الغرفة');location.hash='gathering';}});
async function handleVoiceSignal(roomId,channel,payload){
  if(!payload||payload.to&&payload.to!==sessionUser.id||payload.from===sessionUser.id)return;
  const remoteId=payload.from; let pc=voicePeers[remoteId];
  if(payload.type==='offer'){
    pc=pc||createVoicePeer(roomId,remoteId,false);
    try{await pc.setRemoteDescription(payload.sdp);const queued=voiceIceQueue[remoteId]||[];for(const candidate of queued)await pc.addIceCandidate(candidate);voiceIceQueue[remoteId]=[];await pc.setLocalDescription(await pc.createAnswer());await voiceSignal(channel,{from:sessionUser.id,to:remoteId,type:'answer',sdp:pc.localDescription});}catch(e){console.warn('voice offer handling failed',e);}
  }else if(payload.type==='answer'&&pc){try{await pc.setRemoteDescription(payload.sdp);const queued=voiceIceQueue[remoteId]||[];for(const candidate of queued)await pc.addIceCandidate(candidate);voiceIceQueue[remoteId]=[];}catch(e){console.warn('voice answer handling failed',e);}}
  else if(payload.type==='ice'){
    pc=pc||createVoicePeer(roomId,remoteId,false);
    if(pc.remoteDescription?.type)try{await pc.addIceCandidate(payload.candidate);}catch(e){console.warn('voice ice failed',e);}else(voiceIceQueue[remoteId]||(voiceIceQueue[remoteId]=[])).push(payload.candidate);
  }
}
function startVoicePolling(roomId,channel){
  stopVoicePolling();voiceSignalCursor=new Date(Date.now()-5000).toISOString();
  const poll=async()=>{const {data:rows,error}=await db().rpc('poll_room_voice_signals',{p_room:roomId,p_after:voiceSignalCursor});if(error)return;for(const row of rows||[]){voiceSignalCursor=row.created_at;await handleVoiceSignal(roomId,channel,{...(row.payload||{}),from:row.sender_id,to:row.receiver_id||undefined,type:row.signal_type});}};
  const presence=async()=>{const {data,error}=await db().rpc('list_room_voice_presence',{p_room:roomId});if(!error&&data){const ids=data.map(x=>x.user_id).filter(Boolean);const {data:people}=ids.length?await db().from('profiles').select('id,display_name,username,avatar_url,vip_level').in('id',ids):{data:[]};const byId=Object.fromEntries((people||[]).map(x=>[x.id,x]));voicePresenceCache=data.map(x=>({...x,...(byId[x.user_id]||{})}));connectVoicePeers();refreshVoiceSeats(roomId);}const {data:rules}=await db().from('room_moderations').select('action').eq('room_id',roomId).eq('user_id',sessionUser.id).limit(10);const kicked=(rules||[]).some(x=>x.action==='kick'),muted=(rules||[]).some(x=>x.action==='mute');if(kicked&&activeVoiceRoom?.roomId===roomId){await toggleVoiceRoom(roomId);toast('تم إخراجك من الصوت بواسطة مدير الغرفة');}else if(activeVoiceRoom?.roomId===roomId&&voiceStream){adminVoiceMuted=muted;voiceStream.getAudioTracks().forEach(t=>t.enabled=!voiceMuted&&!adminVoiceMuted);}};
  poll();presence();voiceSignalPollTimer=setInterval(poll,700);voicePresencePollTimer=setInterval(presence,1000);
}
    await new Promise((resolve,reject)=>{let done=false;const timer=setTimeout(()=>{if(!done){done=true;reject(new Error('انتهت مهلة قناة الصوت'));}},10000);channel.subscribe(status=>{if(status==='SUBSCRIBED'&&!done){done=true;clearTimeout(timer);resolve();}else if(['CHANNEL_ERROR','TIMED_OUT','CLOSED'].includes(status)&&!done){done=true;clearTimeout(timer);reject(new Error(status));}});});
    if(!voiceSlotState||voiceSlotState.roomId!==roomId){const occupied=new Set(voicePresenceEntries().map(x=>Number(x.slot)).filter(Number.isInteger));voiceSlotState={roomId,slot:[0,1,2,3,4,5,6,7].find(i=>!occupied.has(i))??0};}await channel.track({user_id:sessionUser.id,display_name:profile.display_name||profile.username,avatar_url:profile.avatar_url||DEFAULT_AVATAR,vip_level:profile.vip_level||0,slot:voiceSlotState.slot});sessionStorage.setItem(VOICE_SESSION_KEY,JSON.stringify({roomId,slot:voiceSlotState.slot}));await db().rpc('set_room_voice_presence',{p_room:roomId,p_slot:voiceSlotState.slot,p_muted:voiceMuted});const {data:muteRule}=await db().from('room_moderations').select('action').eq('room_id',roomId).eq('user_id',sessionUser.id).eq('action','mute').maybeSingle();if(muteRule){adminVoiceMuted=true;}voiceStream.getAudioTracks().forEach(t=>t.enabled=!voiceMuted&&!adminVoiceMuted);connectVoicePeers();refreshVoiceSeats(roomId);startVoicePolling(roomId,channel);toast('تم فتح الصوت؛ انتظر ظهور الطرف الآخر في الغرفة');return true;
  }catch(e){voiceStream?.getTracks().forEach(t=>t.stop());voiceStream=null;stopAllVoiceVisuals();stopVoicePolling();activeVoiceRoom=null;toast(e.name==='NotAllowedError'?'اسمح للموقع باستخدام الميكروفون من إعدادات المتصفح':'تعذر فتح الاتصال الصوتي: '+e.message);return false;}
}
async function toggleVoiceMute(){if(!voiceStream)return toast('افتح الميكروفون أولًا');if(adminVoiceMuted)return toast('الميكروفون مكتوم من مالك الغرفة');voiceMuted=!voiceMuted;voiceStream.getAudioTracks().forEach(t=>{t.enabled=!voiceMuted&&!adminVoiceMuted});if(activeVoiceRoom){sessionStorage.setItem(VOICE_SESSION_KEY,JSON.stringify({roomId:activeVoiceRoom.roomId,slot:voiceSlotState?.slot??0,muted:voiceMuted}));await db().rpc('set_room_voice_presence',{p_room:activeVoiceRoom.roomId,p_slot:voiceSlotState?.slot??0,p_muted:voiceMuted});}document.querySelectorAll('.voice-mute-btn').forEach(b=>b.textContent=voiceMuted?'🔇 فتح الميكروفون':'🎙️ كتم الميكروفون');document.getElementById('voice-activity')?.classList.toggle('muted',voiceMuted||adminVoiceMuted);}
let voiceSlotState=null;const VOICE_SESSION_KEY='webchat-voice-session';
let roomMusicAudio=null,roomMusicEnabled=true,pendingRoomMusic=null,roomMusicRoomId=null;
function stopRoomMusic(){if(roomMusicAudio){roomMusicAudio.pause();roomMusicAudio.src='';roomMusicAudio.remove();roomMusicAudio=null;stopVoiceVisual('music-'+roomMusicRoomId);}roomMusicRoomId=null;document.querySelector('.room-music-player')?.remove();}
async function playRoomMusic(payload){if(!payload?.url)return;stopRoomMusic();roomMusicRoomId=payload.roomId;roomMusicAudio=new Audio(payload.url);roomMusicAudio.loop=true;roomMusicAudio.autoplay=true;roomMusicAudio.volume=.65;roomMusicAudio.controls=false;roomMusicAudio.className='room-music-player';document.body.appendChild(roomMusicAudio);roomMusicAudio.play().catch(()=>console.warn('browser blocked automatic room music'));startVoiceVisual('music-'+payload.roomId,roomMusicAudio,payload.sender_id||payload.sender_name,'music');}
async function openRoomMusicPicker(roomId){if(!activeRoomManagers.has(sessionUser.id))return toast('تشغيل الموسيقى متاح لمالك الغرفة أو مديرها فقط');const input=document.createElement('input');input.type='file';input.accept='audio/*';input.onchange=async()=>{const file=input.files?.[0];if(!file)return;if(file.size>25*1024*1024)return toast('حجم الموسيقى يجب ألا يتجاوز 25MB');const path=`${roomId}/${sessionUser.id}/${Date.now()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const up=await db().storage.from('room-music').upload(path,file,{contentType:file.type,upsert:false});if(up.error)return toast('تعذر رفع الموسيقى: '+up.error.message);const {data:url}=db().storage.from('room-music').getPublicUrl(path);roomMusicEnabled=true;const payload={roomId,url:url.publicUrl,name:file.name,sender_id:sessionUser.id,sender_name:profile.display_name||profile.username};await broadcastRoomEvent(roomId,'music-start',payload);await playRoomMusic(payload);};input.click();}
async function broadcastRoomMusicStop(roomId){if(!activeRoomManagers.has(sessionUser.id))return;stopRoomMusic();await broadcastRoomEvent(roomId,'music-stop',{roomId});}
function voiceSeatPanel(roomId){const manager=activeRoomManagers?.has(sessionUser?.id);return `<div class="panel voice-seat-panel" id="voice-seats-${roomId}"><div class="panel-head"><div><h2>المحادثة الصوتية</h2><small>اضغط + للجلوس في مقعد وفتح الميكروفون</small></div><span class="status">8 مقاعد</span><button class="btn ghost small voice-mute-btn" onclick="toggleVoiceMute()">🎙️ كتم الميكروفون</button></div><div class="voice-music-controls">${manager?`<button class="btn gold small" onclick="openRoomMusicPicker('${roomId}')">🎼 تشغيل أغنية</button><button class="btn danger small" onclick="broadcastRoomMusicStop('${roomId}')">⏹ إغلاق الموسيقى</button>`:''}</div><div id="voice-activity" class="voice-activity"><i></i><i></i><i></i><small>مؤشر الصوت</small></div><div class="voice-seats">${Array.from({length:8},(_,i)=>`<button class="voice-seat" onclick="joinVoiceSlot('${roomId}',${i})"><span class="voice-plus">+</span><small>المقعد ${i+1}</small></button>`).join('')}</div></div>`;}
function refreshVoiceSeats(roomId){const root=document.getElementById('voice-seats-'+roomId);if(!root)return;const remoteUsers=activeVoiceRoom?.roomId===roomId?voicePresenceEntries():[];const seats=root.querySelectorAll('.voice-seat');seats.forEach((el,i)=>{const mine=voiceSlotState&&voiceSlotState.roomId===roomId&&voiceSlotState.slot===i;const remote=remoteUsers.find(x=>Number(x.slot)===i&&!mine)||null;el.classList.toggle('occupied',!!mine);el.dataset.userId=mine?String(sessionUser.id):String(remote?.user_id||'');el.innerHTML=mine?`<img src="${profile.avatar_url||DEFAULT_AVATAR}" alt="صورتك"><b>${escapeHtml(profile.display_name||profile.username||'أنت')}</b><small>🎙️ الميكروفون مفتوح</small>`:remote?`<img src="${escapeHtml(remote.avatar_url||DEFAULT_AVATAR)}" alt=""><b>${escapeHtml(remote.display_name||remote.username||'مستخدم')}</b><small>🔒 المايك محجوز</small>`:`<span class="voice-plus">+</span><small>المقعد ${i+1}</small>`;});}
async function joinVoiceSlot(roomId,slot){const occupied=voicePresenceEntries().find(x=>Number(x.slot)===Number(slot)&&x.user_id!==sessionUser.id);if(occupied)return toast(`المايك رقم ${Number(slot)+1} محجوز بواسطة ${occupied.display_name||occupied.username||'مستخدم'}`);if(activeVoiceRoom&&voiceSlotState?.roomId!==roomId){await toggleVoiceRoom(voiceSlotState.roomId);}if(!activeVoiceRoom)await toggleVoiceRoom(roomId);if(!activeVoiceRoom)return;voiceSlotState={roomId,slot};sessionStorage.setItem(VOICE_SESSION_KEY,JSON.stringify({roomId,slot}));if(activeVoiceRoom?.channel)await activeVoiceRoom.channel.track({user_id:sessionUser.id,display_name:profile.display_name||profile.username,slot});refreshVoiceSeats(roomId);toast('تم فتح الميكروفون ووضع صورتك في المقعد '+(slot+1));}
async function roomPage(id){const {data:room,error}=await db().from('rooms').select('id,name,room_type,game_type,is_open,owner_id,voice_enabled').eq('id',id).single();if(error||!room)return page('الغرفة','gathering',`<div class="panel"><h2>الغرفة غير موجودة</h2><p class="empty">ربما أُغلقت الغرفة أو لا تملك صلاحية الوصول.</p></div>`);const [{data:messages},{data:members},{data:catalog}]=await Promise.all([db().from('messages').select('id,sender_id,body,message_type,created_at').eq('room_id',id).order('created_at',{ascending:true}).limit(100),db().from('room_members').select('user_id').eq('room_id',id).limit(50),db().from('gift_catalog').select('id,name,emoji,price').eq('active',true).order('created_at',{ascending:false}).limit(20)]);const ids=(members||[]).map(m=>m.user_id);const {data:people}=ids.length?await db().from('profiles').select('id,display_name,username,avatar_url,vip_level').in('id',ids):{data:[]};const personById=Object.fromEntries((people||[]).map(p=>[p.id,p]));return page(room.name,'home',`<div class="page-title">${room.voice_enabled?voiceSeatPanel(id):''}<span class="eyebrow">${room.room_type==='gathering'?'تجمع كتابي':'غرفة لعبة'}</span><h1>${escapeHtml(room.name)}</h1><p>هذه الغرفة مخصصة للمحادثات الكتابية فقط. يمكنك إرسال رسائل وهدايا للأعضاء.</p><button class="btn ghost" onclick="location.hash='gathering'"><i class="fa-solid fa-arrow-right"></i> العودة للغرف</button></div><div class="profile-grid"><div class="panel"><div class="panel-head"><h2>المحادثة الكتابية</h2><span class="status">${messages?.length||0} رسالة</span></div><div id="room-messages" style="height:360px;overflow:auto;background:#0b1018;border-radius:14px;padding:12px">${(messages||[]).map(m=>`<div class="${m.message_type==='vip_entry'?'vip-entry-message':''}" style="padding:9px 0;border-bottom:1px solid #ffffff0b"><b style="color:${m.sender_id===sessionUser.id?'var(--gold)':'var(--cyan)'}">${escapeHtml(personById[m.sender_id]?.display_name||personById[m.sender_id]?.username||'مستخدم')} ${personById[m.sender_id]?.vip_level?`<span class="vip-entry-badge vip-${personById[m.sender_id].vip_level}">VIP ${personById[m.sender_id].vip_level}</span>`:''}</b><small style="color:var(--muted);margin-right:8px">${new Date(m.created_at).toLocaleTimeString('ar-EG',{hour:'2-digit',minute:'2-digit'})}</small><p style="margin:4px 0;color:${m.message_type==='system'?'var(--gold)':'var(--text)'}">${escapeHtml(m.body)}</p></div>`).join('')||'<p class="empty">ابدأ أول رسالة في الغرفة.</p>'}</div><div style="display:flex;gap:8px;margin-top:12px"><input id="room-message-input" placeholder="اكتب رسالة..." style="flex:1;padding:12px;border-radius:10px;border:1px solid var(--line);background:#0b1018;color:var(--text)"><button class="btn ghost" onclick="toggleVoiceRecorder('${id}')">🎙️</button><button class="btn gold" onclick="sendRoomMessage('${id}')">إرسال</button></div></div><div class="panel"><div class="panel-head"><h2>أعضاء الغرفة</h2><span>${people?.length||0}</span></div>${(people||[]).map(p=>`<div class="user-result"><img class="vip-avatar vip-${p.vip_level||0}" src="${p.avatar_url||DEFAULT_AVATAR}"><div><b>${escapeHtml(p.display_name||p.username)}</b><small>ID #${p.id.slice(0,8)}</small></div>${p.id!==sessionUser.id?`<button class="btn small ghost" onclick="sendGift('${id}','${p.id}',document.getElementById('gift-select')?.value)">🎁 هدية</button>`:''}</div>`).join('')||'<p class="empty">لا يوجد أعضاء بعد.</p>'}</div><div class="panel" style="margin-top:15px"><div class="panel-head"><h2>الهدايا المتاحة</h2><span>${catalog?.length||0}</span></div>${catalog?.length?`<select id="gift-select" style="width:100%;padding:12px;border-radius:10px;border:1px solid var(--line);background:#0b1018;color:var(--text)">${catalog.map(g=>`<option value="${g.id}">${g.emoji} ${escapeHtml(g.name)} — ${fmt(g.price)} كوينز</option>`).join('')}</select>`:'<p class="empty">لم يضف المطور هدايا بعد.</p>'}</div></div>`);}
async function showGiftPicker(roomId){const [{data:gifts},{data:members}]=await Promise.all([db().from('gift_catalog').select('id,name,emoji,price,image_url').eq('active',true).order('price',{ascending:true}).limit(50),db().from('room_members').select('user_id').eq('room_id',roomId).neq('user_id',sessionUser.id).limit(100)]);const ids=(members||[]).map(x=>x.user_id);const {data:people}=ids.length?await db().from('profiles').select('id,display_name,username').in('id',ids):{data:[]};const modal=document.createElement('div');modal.className='modal-backdrop';modal.innerHTML=`<div class="gift-modal panel"><div class="panel-head"><h2>إرسال هدية</h2><button class="icon-btn" onclick="this.closest('.modal-backdrop').remove()">×</button></div><label>المستلم</label><select id="gift-recipient">${(people||[]).map(x=>`<option value="${x.id}">${escapeHtml(x.display_name||x.username)}</option>`).join('')||'<option value="">لا يوجد أعضاء آخرون</option>'}</select><label>الهدية</label><select id="gift-choice">${(gifts||[]).map(g=>`<option value="${g.id}">${escapeHtml(g.emoji||'🎁')} ${escapeHtml(g.name)} · ${g.price} كوينز</option>`).join('')||'<option value="">لا توجد هدايا متاحة</option>'}</select><button class="btn gold full" onclick="sendRoomGift('${roomId}')">إرسال الهدية</button></div>`;document.body.appendChild(modal);}
let giftRepeatState=null;
function showGiftRepeat(roomId,receiverId,giftId,giftName){document.querySelector('.gift-repeat-action')?.remove();const el=document.createElement('button');el.className='gift-repeat-action';el.innerHTML=`<strong>↻</strong><span>تكرار ${escapeHtml(giftName||'الهدية')}</span>`;el.onclick=()=>sendRoomGift(roomId,receiverId,giftId);document.body.appendChild(el);setTimeout(()=>el.remove(),9000);}
async function sendGiftRecipient(roomId,receiverId,giftId,{repeat=true}={}){const {data:result,error}=await db().rpc('send_room_gift',{p_room:roomId,p_receiver:receiverId,p_gift:giftId});if(error)return {error};const {data:g}=await db().from('gift_catalog').select('name,emoji,image_url,price').eq('id',giftId).maybeSingle();const {data:r}=await db().from('profiles').select('display_name,username').eq('id',receiverId).maybeSingle();const senderName=profile.display_name||profile.username;const receiverName=r?.display_name||r?.username||'عضو الغرفة';await broadcastRoomGift(roomId,{emoji:g?.emoji||'🎁',gift_name:g?.name||'هدية',image_url:g?.image_url,sender_name:senderName,receiver_name:receiverName});if(Number(result?.price||g?.price||0)>300)await broadcastGlobalEvent({room_id:roomId,kind:Number(result?.price||g?.price||0)>2000?'big_gift_2000':'big_gift',title:'هدية كبيرة في غرفة',body:`${senderName} أهدى ${receiverName} الهدية ${g?.name||'هدية'} بقيمة ${fmt(result?.price||g?.price||0)} كوينز.`});const cashback=Number(result?.cashback||0);profile.coins=Number(profile.coins||0)-Number(result?.price||g?.price||0)+cashback;if(cashback)toast(`مردود حظ 🎉 عاد إليك ${fmt(cashback)} كوينز`);return {result,g};}
async function sendRoomGift(roomId,receiverOverride=null,giftOverride=null){const receiver=receiverOverride||document.getElementById('gift-recipient')?.value,gift=giftOverride||document.getElementById('gift-choice')?.value;if(!receiver||!gift)return toast('اختر المستلم والهدية');const out=await sendGiftRecipient(roomId,receiver,gift);toast(out.error?'تعذر إرسال الهدية: '+out.error.message:'تم إرسال الهدية وحفظها في حساب المستلم');document.querySelector('.modal-backdrop')?.remove();if(!out.error){render();setTimeout(()=>showGiftRepeat(roomId,receiver,gift,out.g?.name),120);}}
async function sendGiftToMicUsers(roomId,giftId){const {data:presence}=await db().rpc('list_room_voice_presence',{p_room:roomId});const ids=(presence||[]).map(x=>x.user_id).filter(id=>id!==sessionUser.id);if(!ids.length)return toast('لا يوجد صاعدون على المايك الآن');await sendGiftToRecipients(roomId,ids,giftId);}
async function showMicGiftPicker(roomId){const {data:presence,error}=await db().rpc('list_room_voice_presence',{p_room:roomId});if(error)return toast('تعذر قراءة صاعدي المايك');const ids=(presence||[]).map(x=>x.user_id).filter(id=>id!==sessionUser.id);if(!ids.length)return toast('لا يوجد مستخدمون صاعدون على المايك الآن');const {data:people}=await db().from('profiles').select('id,display_name,username').in('id',ids);const {data:gifts}=await db().from('gift_catalog').select('id,name,emoji,price').eq('active',true).order('price',{ascending:true}).limit(50);const modal=document.createElement('div');modal.className='modal-backdrop';modal.innerHTML=`<div class="gift-modal panel"><div class="panel-head"><h2>هدية لصاعدي المايك</h2><button class="icon-btn" onclick="this.closest('.modal-backdrop').remove()">×</button></div><label>الصاعد</label><select id="mic-gift-recipient"><option value="__all__">🎙️ كل الصاعدين على المايك</option>${(people||[]).map(x=>`<option value="${x.id}">${escapeHtml(x.display_name||x.username)}</option>`).join('')}</select><label>الهدية</label><select id="mic-gift-choice">${(gifts||[]).map(g=>`<option value="${g.id}">${escapeHtml(g.emoji||'🎁')} ${escapeHtml(g.name)} · ${fmt(g.price)}</option>`).join('')}</select><button class="btn gold full" onclick="(document.getElementById('mic-gift-recipient').value==='__all__'?sendGiftToMicUsers('${roomId}',document.getElementById('mic-gift-choice').value):sendRoomGift('${roomId}',document.getElementById('mic-gift-recipient').value,document.getElementById('mic-gift-choice').value))">إرسال لصاعدي المايك</button></div>`;document.body.appendChild(modal);}
async function sendGiftToRecipients(roomId,ids,giftId){let sent=0;for(const id of ids){const out=await sendGiftRecipient(roomId,id,giftId,{repeat:false});if(!out.error)sent++;}document.querySelector('.modal-backdrop')?.remove();toast(`تم إرسال الهدية إلى ${sent} مستخدم`);if(sent)render();}
async function showRoomWideGiftPicker(roomId){const {data:members}=await db().from('room_members').select('user_id').eq('room_id',roomId).neq('user_id',sessionUser.id).limit(100);const ids=(members||[]).map(x=>x.user_id);if(!ids.length)return toast('لا يوجد أعضاء آخرون في الغرفة');const {data:gifts}=await db().from('gift_catalog').select('id,name,emoji,price').eq('active',true).order('price',{ascending:true}).limit(50);const modal=document.createElement('div');modal.className='modal-backdrop';modal.innerHTML=`<div class="gift-modal panel"><div class="panel-head"><h2>هدية لكل الغرفة</h2><button class="icon-btn" onclick="this.closest('.modal-backdrop').remove()">×</button></div><p class="empty">سيتم إرسال نسخة إلى كل عضو موجود في الغرفة (${ids.length}).</p><label>الهدية</label><select id="room-wide-gift-choice">${(gifts||[]).map(g=>`<option value="${g.id}">${escapeHtml(g.emoji||'🎁')} ${escapeHtml(g.name)} · ${fmt(g.price)}</option>`).join('')}</select><button class="btn gold full" onclick="sendGiftToRecipients('${roomId}',[${ids.map(x=>`'${x}'`).join(',')}],document.getElementById('room-wide-gift-choice').value)">إرسال لكل الغرفة</button></div>`;document.body.appendChild(modal);}

let activeVoiceRecorder=null,activeVoiceChunks=[];
async function toggleVoiceRecorder(roomId){if(activeVoiceRecorder){activeVoiceRecorder.stop();return toast('جارٍ تجهيز الرسالة الصوتية');}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});activeVoiceChunks=[];activeVoiceRecorder=new MediaRecorder(stream);activeVoiceRecorder.ondataavailable=e=>{if(e.data.size)activeVoiceChunks.push(e.data)};activeVoiceRecorder.onstop=async()=>{stream.getTracks().forEach(t=>t.stop());const blob=new Blob(activeVoiceChunks,{type:activeVoiceRecorder.mimeType||'audio/webm'});activeVoiceRecorder=null;const path=`${sessionUser.id}/${roomId}-${Date.now()}.webm`;const up=await db().storage.from('voice-messages').upload(path,blob,{contentType:blob.type,upsert:false});if(up.error)return toast('تعذر رفع الرسالة الصوتية: '+up.error.message);const {data:url}=db().storage.from('voice-messages').getPublicUrl(path);const {error}=await db().from('messages').insert({room_id:roomId,sender_id:sessionUser.id,body:url.publicUrl,message_type:'audio'});toast(error?'تعذر حفظ الرسالة الصوتية: '+error.message:'تم إرسال الرسالة الصوتية');if(!error)render();};activeVoiceRecorder.start();toast('بدأ التسجيل، اضغط الزر مرة أخرى للإيقاف');}catch(e){toast('تعذر استخدام الميكروفون: '+e.message);}}
function roomMessageContent(m){return m.message_type==='audio'?`<audio controls preload="metadata" src="${m.body}"></audio>`:escapeHtml(m.body||'');}
async function leaveRoom(roomId){if(activeVoiceRoom?.roomId===roomId){try{await toggleVoiceRoom(roomId);}catch(e){voiceStream?.getTracks().forEach(t=>t.stop());voiceStream=null;activeVoiceRoom=null;}}const {error}=await db().rpc('leave_room',{p_room:roomId});toast(error?'تعذر مغادرة الغرفة: '+error.message:'تمت مغادرة الغرفة وإغلاق الميكروفون');if(!error)location.hash='gathering';}
async function sendRoomMessage(roomId){const input=document.getElementById('room-message-input'),body=input?.value.trim();if(!body)return;const {error}=await db().from('messages').insert({room_id:roomId,sender_id:sessionUser.id,body,message_type:'text'});if(error)toast('تعذر إرسال الرسالة: '+error.message);else{input.value='';render();}}
function showGiftAnimation(emoji,name,image){const old=document.querySelector('.gift-flight');if(old)old.remove();const el=document.createElement('div');el.className='gift-flight';el.innerHTML=`<div class="gift-burst">${image?`<img src="${image}">`:emoji||'🎁'}</div><b>${escapeHtml(name)}</b><span class="spark s1">✦</span><span class="spark s2">✧</span><span class="spark s3">✺</span>`;document.body.appendChild(el);setTimeout(()=>el.remove(),2600);}
async function sendGift(roomId,receiverId,giftId){if(!giftId)return toast('اختر هدية أولاً');const {data:g}=await db().from('gift_catalog').select('id,name,emoji,image_url,price').eq('id',giftId).eq('active',true).maybeSingle();if(!g)return toast('الهدية غير متاحة حالياً');const {error}=await db().from('user_gifts').insert({sender_id:sessionUser.id,receiver_id:receiverId,gift_catalog_id:g.id,gift_name:g.name,gift_image_url:g.image_url||'https://cdn-icons-png.flaticon.com/512/4213/4213958.png',gift_price:g.price});if(error)toast('تعذر إرسال الهدية: '+error.message);else{await db().from('messages').insert({room_id:roomId,sender_id:sessionUser.id,body:`${g.emoji} أرسل ${g.name} بقيمة ${fmt(g.price)} كوينز`,message_type:'gift'});toast('تم إرسال الهدية وحفظها في حساب المستلم');
const {data:receiverProfile}=await db().from('profiles').select('display_name,username').eq('id',receiverId).maybeSingle();
await broadcastRoomGift(roomId,{emoji:g.emoji,name:g.name,gift_name:g.name,image_url:g.image_url,sender_name:profile.display_name||profile.username,receiver_name:receiverProfile?.display_name||receiverProfile?.username||'عضو الغرفة'});
render();}}
async function gathering(){const rooms=await getRooms('gathering');return page('التجمع الممتع','home',`<div class="page-title"><span class="eyebrow">مجتمعك في مكان واحد</span><h1>التجمع الممتع</h1><p>أنشئ غرفًا حقيقية وتظهر فورًا للمستخدمين الآخرين.</p><div class="inline-actions"><button class="btn gold" onclick="createGathering()"><i class="fa-solid fa-plus"></i> إنشاء غرفة</button></div></div><div class="rooms-list">${rooms.map(roomCard).join('')||'<p class="empty">لا توجد غرف تجمع مفتوحة حاليًا.</p>'}</div>`);}
function vipArt(level){return ''; }
async function openConversation(id){window.pendingDeveloperMessage='';await db().from('notifications').update({read_at:new Date().toISOString()}).eq('user_id',sessionUser.id).eq('actor_id',id).is('read_at',null);location.hash='dm/'+id;}
function directMessageContent(m){if(m.message_type==='image')return `<img class="direct-media-image" src="${escapeHtml(m.body)}" alt="صورة مرسلة" loading="lazy">`;if(m.message_type==='audio')return `<audio class="direct-media-audio" controls preload="metadata" src="${escapeHtml(m.body)}"></audio>`;return `<span>${escapeHtml(m.body||'')}</span>`;}
let activeDirectRecorder=null,activeDirectChunks=[];
async function sendDirectImage(recipientId,input){const file=input?.files?.[0];if(!file)return;if(!file.type.startsWith('image/')){toast('اختر ملف صورة فقط');input.value='';return;}if(file.size>8*1024*1024){toast('حجم الصورة يجب ألا يتجاوز 8MB');input.value='';return;}const path=`${sessionUser.id}/${recipientId}/${Date.now()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const up=await db().storage.from('private-chat-media').upload(path,file,{contentType:file.type,upsert:false});if(up.error){toast('تعذر رفع الصورة: '+up.error.message);return;}const {data:url}=db().storage.from('private-chat-media').getPublicUrl(path);const {error}=await db().from('messages').insert({sender_id:sessionUser.id,recipient_id:recipientId,body:url.publicUrl,message_type:'image'});toast(error?'تعذر حفظ الصورة: '+error.message:'تم إرسال الصورة');input.value='';if(!error){await render();setTimeout(()=>{const box=document.querySelector('.conversation-messages');if(box)box.scrollTop=box.scrollHeight;},0);}}
async function toggleDirectVoice(recipientId){if(activeDirectRecorder){activeDirectRecorder.stop();return toast('جارٍ تجهيز الرسالة الصوتية');}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});activeDirectChunks=[];activeDirectRecorder=new MediaRecorder(stream);activeDirectRecorder.ondataavailable=e=>{if(e.data.size)activeDirectChunks.push(e.data)};activeDirectRecorder.onstop=async()=>{stream.getTracks().forEach(t=>t.stop());const recorder=activeDirectRecorder;activeDirectRecorder=null;const blob=new Blob(activeDirectChunks,{type:recorder.mimeType||'audio/webm'});const path=`${sessionUser.id}/${recipientId}/${Date.now()}.webm`;const up=await db().storage.from('private-chat-media').upload(path,blob,{contentType:blob.type,upsert:false});if(up.error)return toast('تعذر رفع الرسالة الصوتية: '+up.error.message);const {data:url}=db().storage.from('private-chat-media').getPublicUrl(path);const {error}=await db().from('messages').insert({sender_id:sessionUser.id,recipient_id:recipientId,body:url.publicUrl,message_type:'audio'});toast(error?'تعذر حفظ الرسالة الصوتية: '+error.message:'تم إرسال الرسالة الصوتية');if(!error)render();};activeDirectRecorder.start();toast('بدأ التسجيل، اضغط الزر مرة أخرى للإرسال');}catch(e){toast('تعذر استخدام الميكروفون: '+e.message);}}
async function showDirectGiftPicker(recipientId){const {data:gifts}=await db().from('gift_catalog').select('id,name,emoji,price,image_url').eq('active',true).order('price',{ascending:true}).limit(50);const modal=document.createElement('div');modal.className='modal-backdrop';modal.innerHTML=`<div class="gift-modal panel"><div class="panel-head"><h2>إرسال هدية خاصة</h2><button class="icon-btn" onclick="this.closest('.modal-backdrop').remove()">×</button></div><select id="direct-gift-choice">${(gifts||[]).map(g=>`<option value="${g.id}">${escapeHtml(g.emoji||'🎁')} ${escapeHtml(g.name)} · ${g.price} كوينز</option>`).join('')||'<option value="">لا توجد هدايا متاحة</option>'}</select><button class="btn gold full" onclick="sendDirectGift('${recipientId}')">إرسال الهدية</button></div>`;document.body.appendChild(modal);}
async function sendDirectGift(recipientId){const gift=document.getElementById('direct-gift-choice')?.value;if(!gift)return toast('لا توجد هدية محددة');const {error}=await db().rpc('send_direct_gift',{p_receiver:recipientId,p_gift:gift});toast(error?(error.message.includes('insufficient_coins')?'رصيدك لا يكفي لإرسال الهدية':'تعذر إرسال الهدية: '+error.message):'تم إرسال الهدية في المحادثة الخاصة');document.querySelector('.modal-backdrop')?.remove();if(!error)render();}
async function conversationPage(id){const {data:person,error}=await db().from('profiles').select('id,username,display_name,avatar_url,vip_level').eq('id',id).single();if(error||!person)return page('المحادثة','notifications',`<div class="panel"><h2>الحساب غير موجود</h2></div>`);const {data:msgs}=await db().from('messages').select('id,sender_id,recipient_id,body,message_type,created_at').or(`and(sender_id.eq.${id},recipient_id.eq.${sessionUser.id}),and(sender_id.eq.${sessionUser.id},recipient_id.eq.${id})`).order('created_at',{ascending:true}).limit(100);return page('المحادثة','notifications',`<div class="page-title"><button class="btn ghost" onclick="location.hash='notifications'">العودة للإشعارات</button><div class="conversation-user"><img class="vip-avatar vip-${person.vip_level||0}" src="${person.avatar_url||DEFAULT_AVATAR}"><div><span class="vip-label animated-vip-name vip-${person.vip_level||0}">${vip(person.vip_level).name}</span><h1>${escapeHtml(person.display_name||person.username)}</h1><p>@${escapeHtml(person.username)}</p></div></div></div><div class="panel conversation-panel"><div id="conversation-messages" class="conversation-messages">${(msgs||[]).map(m=>`<div class="bubble ${m.sender_id===sessionUser.id?'mine':'theirs'}">${directMessageContent(m)}<small>${new Date(m.created_at).toLocaleTimeString('ar-EG',{hour:'2-digit',minute:'2-digit'})}</small></div>`).join('')||'<p class="empty">ابدأ المحادثة الآن.</p>'}</div><div class="conversation-compose"><input id="direct-message-input" placeholder="اكتب رسالة..." value="${escapeHtml(window.pendingDeveloperMessage||'')}"><button class="btn ghost" title="إرسال صورة" onclick="document.getElementById('direct-image-input').click()">🖼️</button><input id="direct-image-input" type="file" accept="image/*" hidden onchange="sendDirectImage('${id}',this)"><button class="btn ghost" title="تسجيل صوت" onclick="toggleDirectVoice('${id}')">🎙️</button><button class="btn ghost" title="إرسال هدية" onclick="showDirectGiftPicker('${id}')">🎁</button><button class="btn gold" onclick="sendDirectMessage('${id}')">إرسال</button></div></div>`);}
async function showSocialList(userId,kind){const labels={followers:'المتابعون',following:'يتابعهم',visitors:'الزوار'};let rows=[];if(kind==='followers'){const {data}=await db().from('follows').select('follower_id').eq('following_id',userId).limit(100);rows=(data||[]).map(x=>x.follower_id);}else if(kind==='following'){const {data}=await db().from('follows').select('following_id').eq('follower_id',userId).limit(100);rows=(data||[]).map(x=>x.following_id);}else{const {data}=await db().from('profile_visits').select('visitor_id').eq('profile_id',userId).order('last_seen_at',{ascending:false}).limit(100);rows=(data||[]).map(x=>x.visitor_id);}const {data:people}=rows.length?await db().from('profiles').select('id,display_name,username,avatar_url,vip_level').in('id',rows):{data:[]};const modal=document.createElement('div');modal.className='social-modal-backdrop';modal.innerHTML=`<div class="social-modal"><button class="modal-close" onclick="this.closest('.social-modal-backdrop').remove()">×</button><h2>${labels[kind]}</h2><div class="social-list">${(people||[]).map(x=>`<div class="social-row" onclick="this.closest('.social-modal-backdrop').remove();openUserProfile('${x.id}')"><img class="vip-avatar vip-${x.vip_level||0}" src="${x.avatar_url||DEFAULT_AVATAR}"><div><b>${escapeHtml(x.display_name||x.username)}</b><small>@${escapeHtml(x.username)} · VIP ${x.vip_level||0}</small></div><i class="fa-solid fa-chevron-left"></i></div>`).join('')||'<p class="empty">لا توجد حسابات بعد.</p>'}</div></div>`;document.body.appendChild(modal);}
async function userPage(id){const {data:person,error}=await db().from('profiles').select('id,username,email,display_name,avatar_url,vip_level,coins,gender').eq('id',id).single();if(error||!person)return page('المستخدم','search',`<div class="panel"><h2>المستخدم غير موجود</h2></div>`);if(id!==sessionUser.id)await db().from('profile_visits').upsert({profile_id:id,visitor_id:sessionUser.id,last_seen_at:new Date().toISOString()},{onConflict:'profile_id,visitor_id'});const [gRes,mRes,follow,backFollow,follower,following,visitors]=await Promise.all([db().from('user_gifts').select('id,gift_name,gift_image_url,sender_id,created_at').eq('receiver_id',id).order('created_at',{ascending:false}).limit(30),db().from('messages').select('id,sender_id,recipient_id,body,created_at').or(`and(sender_id.eq.${id},recipient_id.eq.${sessionUser.id}),and(sender_id.eq.${sessionUser.id},recipient_id.eq.${id})`).order('created_at',{ascending:true}).limit(100),db().from('follows').select('id').eq('follower_id',sessionUser.id).eq('following_id',id).maybeSingle(),db().from('follows').select('id').eq('follower_id',id).eq('following_id',sessionUser.id).maybeSingle(),db().from('follows').select('id',{count:'exact',head:true}).eq('following_id',id),db().from('follows').select('id',{count:'exact',head:true}).eq('follower_id',id),db().from('profile_visits').select('id',{count:'exact',head:true}).eq('profile_id',id)]);const gifts=gRes.data||[],msgs=mRes.data||[];const senderIds=[...new Set(gifts.map(g=>g.sender_id).filter(Boolean))];const {data:senders}=senderIds.length?await db().from('profiles').select('id,display_name,username').in('id',senderIds):{data:[]};const senderNames=Object.fromEntries((senders||[]).map(x=>[x.id,x.display_name||x.username]));const level=Number(person.vip_level||0);const moderationTools=profile.role==='developer'&&window.moderationTarget===id?`<button class="btn danger" onclick="devBanFromProfile('${id}')">حظر</button>`:'';const {data:rel}=await db().from('relationships').select('id,user_a,user_b').or(`user_a.eq.${id},user_b.eq.${id}`).maybeSingle();const partnerId=rel?(rel.user_a===id?rel.user_b:rel.user_a):null;const {data:partner}=partnerId?await db().from('profiles').select('id,display_name,username,avatar_url,vip_level').eq('id',partnerId).single():{data:null};const relationBlock=partner?`<div class="relationship-banner"><span class="relation-link">♡</span><div><b>مرتبطان</b><small>علاقة موثقة بين الحسابين</small></div><div class="relation-pair"><img class="vip-avatar vip-${person.vip_level||0}" src="${person.avatar_url||DEFAULT_AVATAR}"><strong>${escapeHtml(person.display_name||person.username)}</strong><span>♡</span><img class="vip-avatar vip-${partner.vip_level||0}" src="${partner.avatar_url||DEFAULT_AVATAR}"><strong>${escapeHtml(partner.display_name||partner.username)}</strong></div></div>`:`<div class="relationship-banner pending"><span class="relation-link">♡</span><div><b>طلب علاقة</b><small>تُخصم 500 كوينز من كل طرف عند الموافقة</small></div><button class="btn small gold" onclick="requestRelationship('${id}')">إرسال الطلب</button></div>`;return page('ملف المستخدم','search',`<section class="profile-hero vip-profile vip-${level}" style="--vip-art:url('${vipArt(level)}')"><div class="vip-art-layer"></div><div class="vip-hero-image"></div><div class="vip-wings"><i></i><i></i></div><div class="profile-avatar-wrap"><img src="${person.avatar_url||DEFAULT_AVATAR}" class="profile-avatar vip-${level}"></div><div class="profile-identity"><span class="vip-label animated-vip-name vip-${level}">${vip(level).name}</span><h1 class="animated-vip-name vip-${level}">${escapeHtml(person.display_name||person.username)}</h1><p>@${escapeHtml(person.username)} · ID #${person.id.slice(0,8)} <button class="copy-id" onclick="event.stopPropagation();copyId('${person.id}')">نسخ ID</button></p></div><span style="display:flex;gap:7px"><button class="btn gold" onclick="followUser('${id}')">${follow.data?'إلغاء المتابعة':(backFollow.data?'متابعة بالمثل':'متابعة')}</button><button class="btn danger" onclick="reportUser('${id}')">إبلاغ</button></span>${moderationTools}</section>${relationBlock}<div class="stats social-stats"><button onclick="showSocialList('${id}','followers')"><b>${follower.count||0}</b><span>المتابعون</span></button><button onclick="showSocialList('${id}','following')"><b>${following.count||0}</b><span>يتابعهم</span></button><button onclick="showSocialList('${id}','visitors')"><b>${visitors.count||0}</b><span>الزوار</span></button><div><b>VIP ${level}</b><span>المستوى</span></div></div><div class="profile-grid"><div class="panel"><div class="panel-head"><h2>الرسائل الخاصة</h2><span class="status">${msgs.length}</span></div><div style="max-height:300px;overflow:auto">${msgs.map(m=>`<div style="padding:9px;border-bottom:1px solid #ffffff0b"><b style="color:${m.sender_id===sessionUser.id?'var(--gold)':'var(--cyan)'}">${m.sender_id===sessionUser.id?'أنت':escapeHtml(person.display_name||person.username)}</b><p style="margin:4px 0">${escapeHtml(m.body)}</p></div>`).join('')||'<p class="empty">لا توجد رسائل بعد.</p>'}</div><div style="display:flex;gap:8px;margin-top:12px"><input id="direct-message-input" placeholder="اكتب رسالة خاصة..." style="flex:1;padding:12px;border-radius:10px;border:1px solid var(--line);background:#0b1018;color:var(--text)"><button class="btn gold" onclick="sendDirectMessage('${id}')">إرسال</button></div></div><div class="panel gifts"><div class="panel-head"><h2>الهدايا المستلمة</h2><span>${gifts.length}</span></div><div class="gift-grid">${gifts.map(g=>`<div><b>${g.gift_image_url?`<img class="gift-profile-image" src="${escapeHtml(g.gift_image_url)}" alt="">`:'🎁'}</b><small>${escapeHtml(g.gift_name)}</small><small>من: ${escapeHtml(senderNames[g.sender_id]||'مستخدم')}</small></div>`).join('')||'<p class="empty">لا توجد هدايا بعد.</p>'}</div></div></div>`);}
async function sendDirectMessage(recipientId){const input=document.getElementById('direct-message-input'),body=input?.value.trim();if(!body)return;const {error}=await db().from('messages').insert({sender_id:sessionUser.id,recipient_id:recipientId,body,message_type:'text'});if(error)toast('تعذر إرسال الرسالة: '+error.message);else{input.value='';toast('تم إرسال الرسالة الخاصة');render();}}
async function reportUser(id){if(id===sessionUser.id)return toast('لا يمكنك الإبلاغ عن نفسك');const reason=prompt('اكتب سبب الإبلاغ والمشكلة بالتفصيل');if(!reason?.trim())return;const {error}=await db().from('user_reports').insert({reporter_id:sessionUser.id,reported_id:id,reason:reason.trim()});toast(error?'تعذر إرسال البلاغ: '+error.message:'تم إرسال البلاغ إلى المطور للمراجعة');}
async function reviewReport(reportId,userId){const {error}=await db().rpc('developer_review_report',{p_report:reportId,p_action:'reviewed'});if(error)return toast('تعذر فتح البلاغ: '+error.message);window.moderationTarget=userId;location.hash='user/'+userId;}
async function devBanFromProfile(id){const choice=prompt('اكتب permanent للإغلاق النهائي، أو عدد الساعات مثل 6 للإغلاق المؤقت:');if(!choice?.trim())return;const action=choice.trim().toLowerCase()==='permanent'?'permanent':`hours:${Number(choice)}`;if(action.startsWith('hours:')&&(!Number.isInteger(Number(choice))||Number(choice)<1))return toast('أدخل عدد ساعات صحيحًا');const {error}=await db().rpc('developer_set_account_status',{p_user:id,p_action:action});toast(error?'تعذر حظر الحساب: '+error.message:action==='permanent'?'تم حظر الحساب نهائيًا':'تم حظر الحساب لمدة '+choice+' ساعة');}
async function devAccountAction(){const id=document.getElementById('dev-account-id').value.trim(),action=document.getElementById('dev-account-action').value;if(!id)return toast('أدخل UUID الحساب');const {error}=await db().rpc('developer_set_account_status',{p_user:id,p_action:action});toast(error?'تعذر تنفيذ الإجراء: '+error.message:action==='hour'?'تم إغلاق الحساب لمدة ساعة':action==='permanent'?'تم إغلاق الحساب نهائيًا':'تمت إعادة فتح الحساب');}
async function contactDeveloper(channel='WebChat'){const {data:dev}=await db().from('profiles').select('id').eq('role','developer').limit(1).maybeSingle();if(!dev)return toast('لم يتم العثور على حساب المطور');window.pendingDeveloperMessage=`مرحبًا، أريد طلب شحن رصيد عبر ${channel}.`;location.hash='dm/'+dev.id;}
async function profilePage(){const [follower,following,gifts,cashbacks]=await Promise.all([db().from('follows').select('id',{count:'exact',head:true}).eq('following_id',sessionUser.id),db().from('follows').select('id',{count:'exact',head:true}).eq('follower_id',sessionUser.id),db().from('user_gifts').select('id,sender_id,gift_name,gift_image_url,created_at').eq('receiver_id',sessionUser.id).is('converted_at',null).order('created_at',{ascending:false}).limit(100),db().from('gift_cashback_events').select('cashback_amount,cashback_rate,luck_hour,created_at').eq('user_id',sessionUser.id).order('created_at',{ascending:false}).limit(20)]);const cashbackRows=cashbacks.data||[];const cashbackTotal=cashbackRows.reduce((a,x)=>a+Number(x.cashback_amount||0),0);const senderIds=[...new Set((gifts.data||[]).map(g=>g.sender_id).filter(Boolean))];const {data:giftSenders}=senderIds.length?await db().from('profiles').select('id,display_name,username').in('id',senderIds):{data:[]};const senderNames=Object.fromEntries((giftSenders||[]).map(x=>[x.id,x.display_name||x.username]));const giftGroups={};(gifts.data||[]).forEach(g=>{const key=g.gift_name||'هدية';if(!giftGroups[key])giftGroups[key]={...g,count:0,senders:[]};giftGroups[key].count++;if(senderNames[g.sender_id]&&!giftGroups[key].senders.includes(senderNames[g.sender_id]))giftGroups[key].senders.push(senderNames[g.sender_id]);});const groupedGifts=Object.values(giftGroups);return page('الملف الشخصي','profile',`<section class="profile-hero vip-profile vip-${profile.vip_level||0}" style="--vip-art:url('${vipArt(profile.vip_level)}')"><div class="vip-art-layer"></div><div class="vip-hero-image"></div><div class="vip-wings"><i></i><i></i></div><div class="profile-avatar-wrap"><img src="${profile.avatar_url||DEFAULT_AVATAR}" class="profile-avatar vip-${profile.vip_level||0}"><span class="online-ring"></span></div><div><span class="vip-label" style="color:${vip(profile.vip_level).color}">${vip(profile.vip_level).name}</span><h1>${escapeHtml(profile.display_name||profile.username)}</h1><p>@${escapeHtml(profile.username)} · ID #${profile.id.slice(0,8)}</p></div><button class="icon-btn outline" onclick="changeAvatar()"><i class="fa-solid fa-camera"></i></button></section><div class="stats"><div><b>${follower.count||0}</b><span>المتابعون</span></div><div><b>${following.count||0}</b><span>أتابعهم</span></div><div><b>—</b><span>الزوار</span></div><div><b>${fmt(profile.coins)}</b><span>كوينز</span></div></div><div class="panel charge-panel"><div class="panel-head"><h2>شحن الرصيد</h2><span class="status">تواصل مع المطور</span></div><p class="empty">اختر طريقة التواصل، وسيتم فتح حساب المطور داخل WebChat لإرسال طلب الشحن.</p><div class="contact-buttons"><button class="btn gold" onclick="contactDeveloper('WhatsApp')"><i class="fa-brands fa-whatsapp"></i> WhatsApp</button><button class="btn ghost" onclick="contactDeveloper('Instagram')"><i class="fa-brands fa-instagram"></i> Instagram</button><button class="btn ghost" onclick="contactDeveloper('Telegram')"><i class="fa-brands fa-telegram"></i> Telegram</button><button class="btn gold full" onclick="contactDeveloper('WebChat')">مراسلة المطور داخل الموقع</button></div></div><div class="panel cashback-panel"><div class="panel-head"><h2>مردود الهدايا</h2><span class="status">حظ متغير</span></div><p class="empty">المردود خفيف وثابت بنسبة 10% من قيمة الهدية عند تحقق الحظ.</p><div class="cashback-summary"><b>${fmt(cashbackTotal)} كوينز</b><small>${cashbackRows.length} عملية مردود</small></div>${cashbackRows.slice(0,5).map(x=>`<div class="cashback-row"><span>🎉 مردود ${fmt(x.cashback_amount)}</span><small>مردود ثابت ${Number(x.cashback_rate*100).toFixed(0)}% · الساعة ${x.luck_hour}:00</small></div>`).join('')||'<p class="empty">لم تحصل على مردود بعد. جرّب إرسال هدايا.</p>'}</div><div class="profile-grid"><div class="panel"><div class="panel-head"><h2>إدارة الحساب</h2><span class="status">${profile.status==='active'?'نشط':'موقوف'}</span></div><button class="setting" onclick="changeName()"><i class="fa-solid fa-user-pen"></i><span><b>تغيير الاسم</b><small>يُحفظ في قاعدة البيانات</small></span><i class="fa-solid fa-chevron-left"></i></button><button class="setting" onclick="changePassword()"><i class="fa-solid fa-lock"></i><span><b>كلمة المرور</b><small>تحديث عبر Supabase Auth</small></span><i class="fa-solid fa-chevron-left"></i></button><a class="setting" href="app.html#vip"><i class="fa-solid fa-gem"></i><span><b>الترقية</b><small>${vip(profile.vip_level).perk}</small></span><i class="fa-solid fa-chevron-left"></i></a><button class="setting" onclick="openSupport()"><i class="fa-solid fa-headset"></i><span><b>الدعم والشحن</b><small>إرسال طلب حقيقي للمطور</small></span><i class="fa-solid fa-chevron-left"></i></button><button class="setting" onclick="convertGifts()"><i class="fa-solid fa-arrows-rotate"></i><span><b>تحويل الهدايا إلى مال</b><small>يُسجل معاملة وخصم 20%</small></span><i class="fa-solid fa-chevron-left"></i></button></div><div class="panel gifts"><div class="panel-head"><h2>الهدايا المستلمة</h2><span>${gifts.data?.length||0} هدايا</span></div><div class="gift-grid">${groupedGifts.map(g=>`<div><b>${g.gift_image_url?`<img class="gift-profile-image" src="${escapeHtml(g.gift_image_url)}" alt="">`:'🎁'} ${g.count>1?`<sup>${g.count}×</sup>`:''}</b><small>${escapeHtml(g.gift_name)}</small><small>من: ${escapeHtml(g.senders.join('، ')||'مستخدم')}</small></div>`).join('')||'<p class="empty">لا توجد هدايا مستلمة.</p>'}</div></div></div><button class="btn danger full" onclick="logout()">تسجيل الخروج</button>`);}
async function vipPage(){return page('العضوية VIP','vip',`<div class="page-title"><span class="eyebrow">ترقية محفوظة في حسابك</span><h1>مستويات VIP</h1><p>أرسل طلب الترقية للمطور، وسيتم تفعيله على ملفك الحقيقي.</p></div><div class="vip-grid">${VIPS.slice(1).map(v=>`<div class="vip-card ${profile.vip_level===v.level?'current':''}" style="--vip:${v.color}"><div class="vip-top"><span>VIP ${v.level}</span><i class="fa-solid fa-crown"></i></div><h2>${fmt(v.cost)} <small>كوينز</small></h2><p>${v.perk}</p><button class="btn ${profile.vip_level>=v.level?'ghost':'gold'} full" onclick="requestVip(${v.level})">${profile.vip_level===v.level?'مستواك الحالي':profile.vip_level>v.level?'تم فتحه':'طلب الترقية'}</button></div>`).join('')}</div>`);}
async function topPage(){const {data,error}=await db().from('profiles').select('id,username,display_name,coins,vip_level,avatar_url').order('coins',{ascending:false}).limit(20);if(error)throw error;return page('لوحة التوب','top',`<div class="page-title"><span class="eyebrow">بيانات مباشرة من Supabase</span><h1>أغنى اللاعبين</h1><p>الترتيب يتحدث من أرصدة الحسابات الفعلية.</p></div><div class="leaderboard">${(data||[]).map((x,i)=>`<div class="leader clickable-user" onclick="openUserProfile('${x.id}')"><b class="rank">${i+1}</b><img src="${x.avatar_url||DEFAULT_AVATAR}"><div><h3>${escapeHtml(x.display_name||x.username)} ${x.vip_level===5?'♛':''}</h3><small>VIP ${x.vip_level||0} · ID #${x.id.slice(0,8)} <button class="copy-id" onclick="event.stopPropagation();copyId('${x.id}')">نسخ</button></small></div><strong><i class="fa-solid fa-coins"></i> ${fmt(x.coins)}</strong></div>`).join('')||'<p class="empty">لا يوجد مستخدمون بعد.</p>'}</div>`);}
async function searchPage(){return page('البحث','search',`<div class="page-title"><span class="eyebrow">بحث مباشر في الحسابات</span><h1>البحث والاستكشاف</h1><p>ابحث باسم المستخدم أو رقم الـ ID.</p></div><div class="search-box"><i class="fa-solid fa-magnifying-glass"></i><input id="search-input" placeholder="اكتب اسمًا أو ID..." oninput="runSearch(this.value)"></div><div id="search-results"></div>`);}
async function notifications(){const [{data:notes,error},{data:followers},{data:following}]=await Promise.all([db().from('notifications').select('id,actor_id,title,body,kind,room_id,created_at,read_at').eq('user_id',sessionUser.id).order('created_at',{ascending:false}).limit(50),db().from('follows').select('follower_id').eq('following_id',sessionUser.id).limit(200),db().from('follows').select('following_id').eq('follower_id',sessionUser.id).limit(200)]);if(error)throw error;const fIds=(followers||[]).map(x=>x.follower_id),gIds=(following||[]).map(x=>x.following_id),nIds=(notes||[]).map(x=>x.actor_id).filter(Boolean),ids=[...new Set([...fIds,...gIds,...nIds])];const {data:actors}=ids.length?await db().from('profiles').select('id,display_name,username,avatar_url,vip_level').in('id',ids):{data:[]};const byId=Object.fromEntries((actors||[]).map(a=>[a.id,a]));const latest={};(notes||[]).filter(n=>n.actor_id).forEach(n=>{if(!latest[n.actor_id])latest[n.actor_id]=n;});const system=(notes||[]).filter(n=>!n.actor_id);return page('الإشعارات','notifications',`<div class="page-title"><span class="eyebrow">صندوق الوارد الاجتماعي</span><h1>الإشعارات</h1><p>كل الحسابات التي تتابعك أو تتابعها، مع رسائل WebChat وإشعارات النظام.</p></div><div class="inbox"><div class="inbox-account system-inbox"><div class="webchat-logo">W</div><div><b>WebChat</b><small>إشعارات النظام، VIP، البريد والدعم</small></div><span>${system.length}</span></div>${system.map(n=>`<div class="inbox-item system-item"><div class="system-dot">✦</div><div><b>${escapeHtml(n.title)}</b><p>${escapeHtml(n.body)}</p><small>${new Date(n.created_at).toLocaleString('ar-EG')}</small>${n.room_id?`<button class="btn small gold" onclick="event.stopPropagation();location.hash='room/${n.room_id}'">الذهاب</button>`:''}</div></div>`).join('')}${ids.map(id=>{const a=byId[id];if(!a)return '';const tags=[fIds.includes(id)?'يتابعك':'',gIds.includes(id)?'تتابعه':''].filter(Boolean).join(' · ');const n=latest[id];const unread=(notes||[]).filter(x=>x.actor_id===id&&!x.read_at).length;return `<div class="inbox-account person-inbox" onclick="openConversation('${id}')"><img class="notice-avatar vip-avatar vip-${a.vip_level||0}" src="${a.avatar_url||DEFAULT_AVATAR}"><div><b>${escapeHtml(a.display_name||a.username)}</b><small>${tags||'حساب متفاعل'}${n?' · '+escapeHtml(n.title):''}</small><em>${n?escapeHtml(n.body):'اضغط لفتح المحادثة'}</em>${unread?`<span class="unread-count">${unread}</span>`:''}</div><i class="fa-solid fa-chevron-left"></i></div>`;}).join('')||'<p class="empty">لا توجد حسابات بعد.</p>'}</div>`);}
async function runSearch(q){const out=document.getElementById('search-results');if(!out)return;if(!q.trim()){out.innerHTML='';return;}const {data,error}=await db().from('profiles').select('id,username,display_name,avatar_url,vip_level').or(`username.ilike.%${q}%,display_name.ilike.%${q}%`).limit(20);if(error){out.innerHTML='<p class="empty">تعذر تنفيذ البحث.</p>';return;}out.innerHTML=`<div class="search-results">${(data||[]).map(x=>`<div class="user-result"><img src="${x.avatar_url||DEFAULT_AVATAR}" onclick="openUserProfile('${x.id}')" style="cursor:pointer"><div onclick="openUserProfile('${x.id}')" style="cursor:pointer"><b>${escapeHtml(x.display_name||x.username)}</b><small>ID #${x.id.slice(0,8)} · VIP ${x.vip_level||0}</small></div><button class="btn small ghost" onclick="openUserProfile('${x.id}')">الملف</button></div>`).join('')||'<p class="empty">لا توجد نتائج.</p>'}</div>`;}
async function copyId(id){try{await navigator.clipboard.writeText(id);toast('تم نسخ UUID إلى الحافظة');}catch(e){const area=document.createElement('textarea');area.value=id;document.body.appendChild(area);area.select();document.execCommand('copy');area.remove();toast('تم نسخ UUID إلى الحافظة');}}
function openUserProfile(id){location.hash='user/'+id;}
async function followUser(id){if(id===sessionUser.id)return toast('لا يمكنك متابعة نفسك');const {data:existing}=await db().from('follows').select('id').eq('follower_id',sessionUser.id).eq('following_id',id).maybeSingle();if(existing){const {error}=await db().from('follows').delete().eq('id',existing.id);toast(error?'تعذر إلغاء المتابعة: '+error.message:'تم إلغاء المتابعة');}else{const {error}=await db().from('follows').insert({follower_id:sessionUser.id,following_id:id});if(error)toast('تعذر المتابعة: '+error.message);else{await db().from('notifications').insert({user_id:id,actor_id:sessionUser.id,title:'متابع جديد',body:`${profile.display_name||profile.username} بدأ بمتابعتك`,kind:'follow'});toast('تمت المتابعة');}}render();}
async function requestRelationship(targetId){if(targetId===sessionUser.id)return toast('لا يمكنك إنشاء علاقة مع نفسك');const {error}=await db().rpc('request_relationship',{p_target:targetId});toast(error?'تعذر إرسال طلب العلاقة: '+error.message:'تم إرسال طلب العلاقة. عند الموافقة يخصم 500 كوينز من كل طرف');}
async function acceptRelationshipFrom(actorId){const {data:r}=await db().from('relationship_requests').select('id').eq('requester_id',actorId).eq('target_id',sessionUser.id).eq('status','pending').order('created_at',{ascending:false}).limit(1).maybeSingle();if(!r)return toast('الطلب غير موجود أو تمت معالجته');return acceptRelationship(r.id);}
async function rejectRelationshipFrom(actorId){const {data:r}=await db().from('relationship_requests').select('id').eq('requester_id',actorId).eq('target_id',sessionUser.id).eq('status','pending').order('created_at',{ascending:false}).limit(1).maybeSingle();if(!r)return toast('الطلب غير موجود أو تمت معالجته');return rejectRelationship(r.id);}
async function acceptRelationship(requestId){const {error}=await db().rpc('accept_relationship',{p_request:requestId});toast(error?'تعذر قبول العلاقة: '+error.message:'تم قبول العلاقة وخصم 500 كوينز من كل طرف');render();}
async function rejectRelationship(requestId){const {error}=await db().rpc('reject_relationship',{p_request:requestId});toast(error?'تعذر رفض العلاقة: '+error.message:'تم رفض طلب العلاقة');render();}
async function queueForGame(game,bet){const box=document.getElementById('match-status');if(!box)return;box.style.display='block';let seconds=15;const rotating=['سالم','لاعب VIP','مهاجم سريع','عاشق Roulette','لاعب جديد','Shadow'];box.innerHTML=`<div class="match-queue"><div class="queue-wheel">${game==='Roulette'?'🎡':'🎮'}</div><h2>جاري البحث عن لاعبين</h2><p>اللعبة: <b>${escapeHtml(game)}</b> · الرهان: <b>${bet} كوينز</b></p><div class="queue-counter">${seconds}</div><div class="queue-players" id="queue-players"></div><small>يتغير اللاعبون المنتظرون تلقائيًا حتى اكتمال المطابقة...</small></div>`;const timer=setInterval(()=>{seconds--;const c=document.querySelector('.queue-counter');if(c)c.textContent=Math.max(seconds,0);const list=document.getElementById('queue-players');if(list)list.innerHTML=[0,1,2].map((_,i)=>`<span>● ${rotating[Math.floor(Math.random()*rotating.length)]}</span>`).join('');if(seconds<=0){clearInterval(timer);const b=document.getElementById('match-status');if(b)b.innerHTML+=`<div class="robot-offer"><p>لم نجد لاعبين كافيين الآن.</p><button class="btn gold" onclick="startRobotMatch('${game}',${bet})">هل تريد اللعب مع الـRobot؟</button></div>`;}},1000);const {data,error}=await db().rpc('join_game_match',{p_game_type:game,p_bet_amount:bet});if(error&&box)box.innerHTML+=`<p class="empty">تعذر تسجيل قائمة الانتظار: ${escapeHtml(error.message)}</p>`;else if(data?.status==='playing'&&box){clearInterval(timer);box.innerHTML=`<div class="match-queue"><div class="queue-wheel">🎉</div><h2>بدأت المباراة</h2><p>${escapeHtml(data.game_type)} · الرهان ${data.bet_amount} كوينز</p><span class="status">عدد اللاعبين: ${data.players}</span></div>`;}}
async function inspectMatch(id){const {data,error}=await db().from('game_matches').select('id,game_type,bet_amount,max_players,status,started_at').eq('id',id).single();if(error)return toast('تعذر قراءة المباراة');const {count}=await db().from('game_match_players').select('user_id',{count:'exact',head:true}).eq('match_id',id);toast(data.status==='playing'?`بدأت ${data.game_type} مع ${count} لاعبين`:`ما زلنا نبحث عن لاعبين (${count}/${data.max_players})`);}
async function joinRoom(id){const {data:room}=await db().from('rooms').select('is_private').eq('id',id).single();const password=room?.is_private?prompt('هذه غرفة خاصة. أدخل كلمة المرور:'):null;if(room?.is_private&&password===null)return;const {data,error}=await db().rpc('join_chat_room',{p_room:id,p_password:password});if(error){toast(error.message.includes('invalid_room_password')?'كلمة المرور غير صحيحة':'تعذر الانضمام للغرفة: '+error.message);return;}const msg=await db().from('messages').insert({room_id:id,sender_id:sessionUser.id,body:`${vip(profile.vip_level).level?`✨ ${profile.display_name||profile.username} دخل بإطلالة ${vip(profile.vip_level).name} 👑`:`${profile.display_name||profile.username} انضم إلى الغرفة`}`,message_type:profile.vip_level?'vip_entry':'system'});if(msg.error)toast('تم الانضمام لكن تعذر تسجيل رسالة الدخول: '+msg.error.message);if(profile.vip_level){const entry={room:id,display_name:profile.display_name,username:profile.username,avatar_url:profile.avatar_url,vip_level:profile.vip_level};sessionStorage.setItem('webchat-vip-entry',JSON.stringify(entry));broadcastRoomEvent(id,'vip-entry',entry);}location.hash='room/'+id;}
async function createGameRoom(game,bet){const {data,error}=await db().from('rooms').insert({owner_id:sessionUser.id,name:`غرفة ${game} · ${profile.display_name}`,room_type:'game',game_type:game,bet_amount:bet,cover_emoji:game==='Ludo'?'🎲':'🎡'}).select('id').single();if(error)toast('تعذر إنشاء الغرفة: '+error.message);else{await db().from('room_members').insert({room_id:data.id,user_id:sessionUser.id});toast('تم إنشاء غرفة حقيقية');location.hash='gathering';}}
async function createGathering(){const name=prompt('اكتب اسم الغرفة');if(!name?.trim())return;const mode=prompt('اكتب 1 لغرفة مفتوحة للجميع، أو 2 لغرفة خاصة بكلمة مرور','1');if(mode!=='1'&&mode!=='2')return;const isPrivate=mode==='2';const password=isPrivate?prompt('اكتب كلمة مرور الغرفة (4 أحرف على الأقل)'):null;if(isPrivate&&(!password||password.length<4))return toast('كلمة المرور يجب أن تكون 4 أحرف على الأقل');const voice=confirm('هل تريد تفعيل المحادثة الصوتية داخل الغرفة؟');let {data,error}=await db().rpc('create_chat_room',{p_name:name.trim(),p_private:isPrivate,p_password:password,p_voice:voice});if(error&&!isPrivate){const fallback=await db().from('rooms').insert({owner_id:sessionUser.id,name:name.trim(),room_type:'gathering',cover_emoji:'✨',is_private:false,voice_enabled:voice,is_open:true,last_activity_at:new Date().toISOString()}).select('id').single();if(!fallback.error){await db().from('room_members').insert({room_id:fallback.data.id,user_id:sessionUser.id});data=fallback.data.id;error=null;}}if(error)toast('تعذر إنشاء الغرفة: '+(error.message||'تحقق من اتصال الحساب بقاعدة البيانات'));else{toast(voice?'تم إنشاء غرفة كتابية وصوتية':'تم إنشاء الغرفة وحفظها');location.hash='room/'+data;}}
async function changeName(){const n=prompt('الاسم الجديد',profile.display_name||profile.username);if(!n?.trim())return;const {error}=await db().from('profiles').update({display_name:n.trim(),username:n.trim(),updated_at:new Date().toISOString()}).eq('id',sessionUser.id);if(error)toast('تعذر تحديث الاسم: '+error.message);else{await db().auth.updateUser({data:{full_name:n.trim()}});profile=await getProfile();toast('تم تحديث الاسم في قاعدة البيانات');render();}}
function changeAvatar(){const modal=document.createElement('div');modal.className='modal-backdrop';modal.innerHTML=`<div class="panel avatar-upload-modal"><div class="panel-head"><h2>تغيير صورة الحساب</h2><button class="icon-btn" onclick="this.closest('.modal-backdrop').remove()">×</button></div><p class="empty">اختر صورة من جهازك ثم اضغط «رفع الصورة». يتم حفظها في تخزين الموقع وإضافة رابطها تلقائيًا للحساب.</p><input id="avatar-file-input" type="file" accept="image/jpeg,image/png,image/webp,image/gif"><button class="btn gold full" onclick="uploadAvatarImage()">رفع الصورة</button></div>`;document.body.appendChild(modal);}
async function uploadAvatarImage(){const input=document.getElementById('avatar-file-input'),file=input?.files?.[0];if(!file)return toast('اختر صورة أولًا');if(file.size>8*1024*1024)return toast('حجم الصورة يجب ألا يتجاوز 8MB');const ext=(file.name.split('.').pop()||'jpg').toLowerCase().replace(/[^a-z0-9]/g,'')||'jpg';const path=`${sessionUser.id}/${Date.now()}.${ext}`;const up=await db().storage.from('profile-avatars').upload(path,file,{contentType:file.type,upsert:false});if(up.error)return toast('تعذر رفع الصورة: '+up.error.message);const {data:url}=db().storage.from('profile-avatars').getPublicUrl(path);const {error}=await db().from('profiles').update({avatar_url:url.publicUrl,updated_at:new Date().toISOString()}).eq('id',sessionUser.id);if(error)return toast('تم رفع الصورة لكن تعذر ربطها بالحساب: '+error.message);profile.avatar_url=url.publicUrl;document.querySelector('.modal-backdrop')?.remove();toast('تم رفع صورة الحساب بنجاح');render();}
async function changePassword(){const n=prompt('كلمة المرور الجديدة (6 أحرف على الأقل)');if(!n||n.length<6)return toast('كلمة المرور يجب أن تكون 6 أحرف على الأقل');const {error}=await db().auth.updateUser({password:n});toast(error?'تعذر تغيير كلمة المرور: '+error.message:'تم تغيير كلمة المرور عبر Supabase Auth');}
async function requestVip(level){const {error}=await db().from('support_tickets').insert({user_id:sessionUser.id,subject:`طلب ترقية VIP ${level}`,description:`أطلب تفعيل VIP ${level} للحساب ${profile.id}`,status:'pending'});toast(error?'تعذر إرسال الطلب: '+error.message:'تم إرسال طلب VIP للمطور وحُفظ في قاعدة البيانات');}
async function openSupport(){const text=prompt('اكتب طلب الشحن أو المشكلة');if(!text?.trim())return;const {error}=await db().from('support_tickets').insert({user_id:sessionUser.id,subject:'طلب دعم وشحن',description:text.trim(),status:'pending'});toast(error?'تعذر إرسال الطلب: '+error.message:'تم إرسال الطلب للمطور');}
async function convertGifts(){const {data,error}=await db().rpc('convert_received_gifts');if(error)return toast(error.message.includes('no_gifts')?'لا توجد هدايا جديدة للتحويل':'تعذر تحويل الهدايا: '+error.message);toast(`تم تحويل ${fmt(data.net_value)} كوينز بعد خصم 20% من قيمة ${fmt(data.gift_value)}؛ عدد الهدايا ${data.count}`);render();}
function mailToReset(t){const code=(t.description.match(/رمز التحقق:\s*([0-9]{6})/)||[])[1]||'';const email=(t.description.match(/البريد:\s*([^\s—]+)/)||[])[1]||'';const subject=encodeURIComponent('رمز إعادة تعيين كلمة المرور');const body=encodeURIComponent(`مرحبًا،

رمز التحقق الخاص بك هو: ${code}

هذا الرمز صالح لمدة 15 دقيقة. بعد التحقق منه استخدم رابط إعادة تعيين كلمة المرور الآمن.`);return `mailto:${email}?subject=${subject}&body=${body}`;}
async function developerPage(){if(profile.role!=='developer')return page('غير مصرح','home',`<div class="panel"><h2>غير مصرح</h2><p class="empty">هذه الصفحة متاحة لحسابات المطور فقط.</p></div>`);const {data: tickets}=await db().from('support_tickets').select('id,user_id,subject,description,status,created_at').eq('status','pending').order('created_at',{ascending:false}).limit(50);const {data: reports}=await db().from('user_reports').select('id,reporter_id,reported_id,reason,created_at').eq('status','pending').order('created_at',{ascending:false}).limit(50);return page('لوحة المطور','home',`<div class="page-title"><span class="eyebrow">Developer control center</span><h1>لوحة المطور</h1><p>هذه العمليات تُكتب مباشرة في قاعدة البيانات الحقيقية.</p></div><div class="dev-grid"><div class="panel"><div class="panel-head"><h2>شحن رصيد</h2><span class="status">صلاحية المطور</span></div><div class="field dev-field"><label>معرّف المستخدم UUID <span class="hint">انسخه من ملف الحساب</span></label><input id="dev-id" placeholder="الصق UUID هنا"></div><div class="field dev-field"><label>الرصيد الجديد</label><input id="dev-coins" type="number"></div><button class="btn gold full" onclick="devRecharge()">حفظ الرصيد</button></div><div class="panel"><div class="panel-head"><h2>خصم رصيد</h2><span class="status">عملية مسجلة</span></div><div class="field dev-field"><label>معرّف المستخدم UUID</label><input id="dev-debit-id" placeholder="الصق UUID هنا"></div><div class="field dev-field"><label>المبلغ المراد خصمه</label><input id="dev-debit-amount" type="number" min="0.01" step="0.01" placeholder="مثال: 500"></div><div class="field dev-field"><label>سبب الخصم اختياري</label><input id="dev-debit-reason" placeholder="مثال: تسوية أو استرجاع"></div><button class="btn danger full" onclick="devDebitCoins()">خصم الرصيد</button></div><div class="panel"><div class="panel-head"><h2>تفعيل VIP</h2><span class="status">صلاحية المطور</span></div><div class="field dev-field"><label>معرّف المستخدم UUID <span class="hint">انسخه من ملف الحساب</span></label><input id="dev-vip-id" placeholder="الصق UUID هنا"></div><div class="field dev-field"><label>المستوى</label><select id="dev-level"><option value="1">VIP 1</option><option value="2">VIP 2</option><option value="3">VIP 3</option><option value="4">VIP 4</option><option value="5">VIP 5</option></select></div><button class="btn gold full" onclick="devVip()">حفظ الترقية</button></div></div><div class="panel moderation-panel" style="margin-top:15px"><div class="panel-head"><h2>إدارة الحسابات</h2><span class="status">بالـ UUID</span></div><div class="field dev-field"><label>UUID الحساب</label><input id="dev-account-id" placeholder="الصق ID الحساب"></div><div class="field dev-field"><label>الإجراء</label><select id="dev-account-action"><option value="hour">إغلاق مؤقت لمدة ساعة</option><option value="permanent">إغلاق نهائي</option><option value="restore">إعادة فتح الحساب</option></select></div><button class="btn danger full" onclick="devAccountAction()">تنفيذ الإجراء</button></div><div class="panel reports-panel" style="margin-top:15px"><div class="panel-head"><h2>بلاغات المستخدمين</h2><span>${reports?.length||0}</span></div>${(reports||[]).map(r=>`<div class="notice"><div><b>بلاغ عن حساب</b><p>${escapeHtml(r.reason)}</p><small>المبلّغ: ${r.reporter_id} · الحساب: ${r.reported_id}</small></div><span style="display:flex;gap:6px"><button class="btn small gold" onclick="reviewReport('${r.id}','${r.reported_id}')">مراجعة</button><button class="btn small ghost" onclick="reviewReport('${r.id}','dismissed')">تجاهل</button></span></div>`).join('')||'<p class="empty">لا توجد بلاغات معلقة.</p>'}</div><div class="panel broadcast-panel" style="margin-top:15px"><div class="panel-head"><h2>إشعار جماعي</h2><span class="status">يصل لجميع الحسابات</span></div><div class="field dev-field"><label>عنوان الإشعار</label><input id="broadcast-title" placeholder="رسالة من WebChat"></div><div class="field dev-field"><label>نص الإشعار</label><textarea id="broadcast-body" placeholder="اكتب الإعلان أو التنبيه هنا"></textarea></div><button class="btn gold full" onclick="devBroadcast()">إرسال إلى جميع المستخدمين</button></div><div class="panel" style="margin-top:15px"><div class="panel-head"><h2>البلاغات وطلبات الدعم</h2><span>${tickets?.length||0}</span></div>${(tickets||[]).map(t=>`<div class="notice"><div><b>${escapeHtml(t.subject)}</b><p>${escapeHtml(t.description)}</p><small>${t.user_id} · ${t.status}</small></div>${t.subject.startsWith('طلب ترقية VIP')?`<span style="display:flex;gap:6px"><button class="btn small gold" onclick="approveVip('${t.id}','${t.user_id}')">ترقية</button><button class="btn small ghost" onclick="reviewVipAccount('${t.user_id}')">مراجعة الحساب</button><button class="btn small danger" onclick="rejectVip('${t.id}','${t.user_id}')">رفض</button></span>`:t.subject.startsWith('طلب إعادة تعيين')?`<span style="display:flex;gap:6px"><a class="btn small gold" href="${mailToReset(t)}" target="_blank">فتح البريد الجاهز</a><button class="btn small ghost" onclick="approvePasswordReset('${t.id}','${t.user_id}')">إرسال رابط آمن</button></span>`:`<button class="btn small ghost" onclick="closeTicket('${t.id}')">إغلاق</button>`}</div>`).join('')||'<p class="empty">لا توجد طلبات.</p>'}</div><div class="panel" style="margin-top:15px"><div class="panel-head"><h2>إنشاء هدية جديدة</h2><span class="status">تظهر للمستخدمين</span></div><div class="dev-grid"><div class="field dev-field"><label>اسم الهدية</label><input id="gift-name" placeholder="تاج ملكي"></div><div class="field dev-field"><label>الإيموجي</label><input id="gift-emoji" placeholder="👑"></div><div class="field dev-field"><label>السعر بالكوينز</label><input id="gift-price" type="number" placeholder="100"></div><div class="field dev-field"><label>رابط الصورة اختياري</label><input id="gift-image" placeholder="https://..."></div></div><button class="btn gold full" onclick="devCreateGift()">إضافة الهدية</button></div>`);}
async function devBroadcast(){const title=document.getElementById('broadcast-title')?.value.trim(),body=document.getElementById('broadcast-body')?.value.trim();if(!title||!body)return toast('اكتب عنوان الإشعار ونصه');const {data,error}=await db().rpc('broadcast_notification',{p_title:title,p_body:body,p_kind:'system'});toast(error?'تعذر الإرسال: '+error.message:`تم إرسال الإشعار إلى ${data||0} مستخدم`);if(!error){document.getElementById('broadcast-title').value='';document.getElementById('broadcast-body').value='';}}
async function devCreateGift(){const name=document.getElementById('gift-name').value.trim(),emoji=document.getElementById('gift-emoji').value.trim()||'🎁',price=Number(document.getElementById('gift-price').value),image=document.getElementById('gift-image').value.trim()||null;if(!name||!Number.isFinite(price)||price<0)return toast('أدخل اسمًا وسعرًا صحيحًا');const {error}=await db().from('gift_catalog').insert({name,emoji,price,image_url:image,created_by:sessionUser.id});toast(error?'تعذر إضافة الهدية: '+error.message:'تمت إضافة الهدية وأصبحت متاحة للمستخدمين');render();}
async function devRecharge(){const id=document.getElementById('dev-id').value.trim(),coins=Number(document.getElementById('dev-coins').value);if(!id||!Number.isFinite(coins)||coins<0)return toast('أدخل UUID ورصيدًا صحيحًا');const {error}=await db().rpc('developer_set_coins',{p_user:id,p_coins:coins});toast(error?'تعذر شحن الرصيد: '+error.message:'تم شحن الرصيد وحفظه في قاعدة البيانات');}
async function devDebitCoins(){const id=document.getElementById('dev-debit-id')?.value.trim(),amount=Number(document.getElementById('dev-debit-amount')?.value),reason=document.getElementById('dev-debit-reason')?.value.trim()||null;if(!id||!Number.isFinite(amount)||amount<=0)return toast('أدخل UUID ومبلغ خصم صحيحًا');if(!confirm(`سيتم خصم ${amount.toLocaleString('ar-EG')} كوينز من هذا الحساب. هل تريد المتابعة؟`))return;const {data,error}=await db().rpc('developer_debit_coins',{p_user:id,p_amount:amount,p_reason:reason});if(error){const msg=error.message.includes('insufficient_coins')?'رصيد الحساب غير كافٍ':error.message.includes('user_not_found')?'الحساب غير موجود':error.message.includes('developer_only')?'هذه العملية للمطور فقط':'تعذر خصم الرصيد: '+error.message;return toast(msg);}toast(`تم خصم ${Number(data?.deducted||amount).toLocaleString('ar-EG')} كوينز. الرصيد الجديد: ${Number(data?.balance||0).toLocaleString('ar-EG')}`);document.getElementById('dev-debit-amount').value='';document.getElementById('dev-debit-reason').value='';}
async function devVip(){const id=document.getElementById('dev-vip-id').value.trim(),level=Number(document.getElementById('dev-level').value);if(!id||!Number.isInteger(level)||level<0||level>5)return toast('أدخل UUID ومستوى VIP صحيحًا');const {error}=await db().rpc('developer_set_vip',{p_user:id,p_level:level});toast(error?'تعذر تفعيل VIP: '+error.message:'تم تفعيل VIP وحفظه في قاعدة البيانات');}
async function approvePasswordReset(ticketId,userId){const {data:p}=await db().from('profiles').select('email').eq('id',userId).single();if(!p?.email)return toast('لا يوجد بريد مرتبط بالحساب');const sent=await db().auth.resetPasswordForEmail(p.email,{redirectTo:location.origin+'/index.html'});if(sent.error)return toast('تعذر إرسال رابط الاستعادة: '+sent.error.message);await db().from('support_tickets').update({status:'approved'}).eq('id',ticketId);await db().from('notifications').insert({user_id:userId,title:'تم اعتماد إعادة التعيين',body:'أرسل المطور رابطًا آمنًا إلى بريدك الإلكتروني لتعيين كلمة مرور جديدة','kind':'password_reset'});toast('تم إرسال رابط إعادة التعيين الآمن إلى بريد المستخدم');render();}
async function closeTicket(id){const {error}=await db().from('support_tickets').update({status:'closed'}).eq('id',id);toast(error?'تعذر تحديث البلاغ: '+error.message:'تم إغلاق البلاغ');render();}
function reviewVipAccount(userId){window.moderationTarget=userId;location.hash='user/'+userId;}
async function approveVip(ticketId,userId){const {data:t,error}=await db().from('support_tickets').select('subject').eq('id',ticketId).eq('status','pending').single();if(error)return toast('الطلب غير موجود أو تمت معالجته');const m=t.subject.match(/VIP\s*(\d+)/i),level=m?Number(m[1]):1;const result=await db().rpc('developer_decide_vip',{p_ticket:ticketId,p_user:userId,p_level:level,p_accept:true});if(result.error)return toast('تعذر اعتماد الترقية: '+result.error.message);toast('تمت ترقية المستخدم واختفى الطلب من القائمة');render();}
async function rejectVip(ticketId,userId){const result=await db().rpc('developer_decide_vip',{p_ticket:ticketId,p_user:userId,p_level:0,p_accept:false});if(result.error)return toast('تعذر رفض الطلب: '+result.error.message);toast('تم رفض الطلب واختفاؤه من القائمة');render();}

async function sendRoomMessage(roomId){const input=document.getElementById('room-message-input'),body=input?.value.trim();if(!body)return;const {error}=await db().from('messages').insert({room_id:roomId,sender_id:sessionUser.id,body,message_type:'text'});if(error)toast('تعذر إرسال الرسالة: '+error.message);else{input.value='';render();}}
let activeRoomOwnerId=null,activeRoomManagers=new Set();
async function setRoomAdmin(roomId,userId,enabled){if(activeRoomOwnerId!==sessionUser.id)return toast('تعيين المدراء متاح لمالك الغرفة فقط');const {error}=await db().rpc('set_room_admin',{p_room:roomId,p_user:userId,p_enabled:enabled});toast(error?'تعذر تحديث مدير الغرفة: '+error.message:(enabled?'تم تعيين العضو مديرًا':'تمت إزالة صلاحية المدير'));if(!error)render();}
async function moderateRoomMember(roomId,userId,action){
  if(!activeRoomManagers.has(sessionUser.id))return toast('هذه الصلاحية لمالك الغرفة أو مديرها فقط');
  const {error}=await db().rpc('moderate_room_member',{p_room:roomId,p_user:userId,p_action:action});
  if(error)return toast('تعذر تنفيذ الإجراء: '+error.message);
  if(activeVoiceRoom?.roomId===roomId)await activeVoiceRoom.channel.send({type:'broadcast',event:'voice-admin',payload:{to:userId,action}});
  toast(action==='kick'?'تم طرد المستخدم من الغرفة':action==='mute'?'تم كتم الميكروفون':'تم إلغاء الكتم');render();
}
function showVipEntryBurst(person){
  document.querySelector('.vip-entry-burst')?.remove();const el=document.createElement('div');el.className='vip-entry-burst';
  const level=Number(person.vip_level||0);el.innerHTML=`<div class="vip-entry-crown">♛</div><img src="${escapeHtml(person.avatar_url||DEFAULT_AVATAR)}" alt="${escapeHtml(person.display_name||person.username||'مستخدم')}"><strong>${escapeHtml(person.display_name||person.username||'مستخدم')}</strong><span>دخل الغرفة بإطلالة VIP ${level}</span><b>✦ ترحيب ملكي ✦</b>`;document.body.appendChild(el);setTimeout(()=>el.remove(),4200);
}
async function openRoomGamePicker(roomId){
  const modal=document.createElement('div');modal.className='modal-backdrop';
  modal.innerHTML=`<div class="match-modal panel"><div class="panel-head"><h2>ألعاب الغرفة</h2><button class="icon-btn" onclick="this.closest('.modal-backdrop').remove()">×</button></div><p class="empty">اختر لعبة ليبدأ الموجودون في الغرفة المطابقة عليها. كل لاعب يختار نفس الرهان.</p><div class="room-game-grid">${[['Ludo','🎲','لودو'],['Domino','🀄','دومينو'],['Race','🏎️','سباق السيارات'],['Ahkam','🏛️','الأحكام']].map(x=>`<button class="btn ghost" onclick="startRoomGame('${roomId}','${x[0]}')">${x[1]} ${x[2]}</button>`).join('')}</div></div>`;document.body.appendChild(modal);
}
function launchMatchedGame(game,matchId,bet,roomId){const file={Ludo:'ludo.html',Domino:'domino.html',Race:'race.html',Ahkam:'ahkam.html'}[game];if(file)location.href=`games/${file}?match=${matchId}&bet=${bet}&room=${roomId||''}`;}
async function startRoomGame(roomId,game){const bet=Number(prompt('اكتب الرهان: 100 أو 200 أو 300 أو 400 أو 500','100'));if(![100,200,300,400,500].includes(bet))return toast('قيمة الرهان غير صحيحة');const {data,error}=await db().rpc('join_game_match',{p_game_type:game,p_bet_amount:bet});if(error)return toast('تعذر دخول المطابقة: '+error.message);const matchId=data?.match_id||data?.id;if(!matchId)return toast('لم يتم إنشاء رقم المباراة');const status=data?.status==='playing'?'بدأت المباراة الآن':'أنت في قائمة الانتظار؛ سيتم نقلك تلقائيًا عند دخول صديقك';await db().from('messages').insert({room_id:roomId,sender_id:sessionUser.id,body:`🎮 ${profile.display_name||profile.username} اختار لعبة ${game} برهان ${bet}. ${status}`,message_type:'game_system'});toast(status);if(data?.status==='playing')return launchMatchedGame(game,matchId,bet,roomId);const timer=setInterval(async()=>{const {data:m}=await db().from('game_matches').select('id,status').eq('id',matchId).maybeSingle();if(m?.status==='playing'){clearInterval(timer);launchMatchedGame(game,matchId,bet,roomId);}},900);setTimeout(()=>clearInterval(timer),120000);}

async function roomPage(id){
  const [{data:room,error},{data:messages},{data:members},{data:catalog},{data:admins},{data:moderations}]=await Promise.all([
    db().from('rooms').select('id,name,room_type,game_type,is_open,owner_id,is_private,voice_enabled').eq('id',id).single(),
    db().from('messages').select('id,sender_id,body,message_type,created_at').eq('room_id',id).order('created_at',{ascending:true}).limit(200),
    db().from('room_members').select('user_id').eq('room_id',id).limit(100),
    db().from('gift_catalog').select('id,name,emoji,price,image_url').eq('active',true).order('price',{ascending:true}).limit(50),
    db().rpc('list_room_admins',{p_room:id}),
    db().from('room_moderations').select('user_id,action').eq('room_id',id).limit(200)
  ]);if(error||!room)return page('الغرفة','gathering',`<div class="panel"><h2>الغرفة غير موجودة</h2></div>`);
  let memberRows=members||[];if(!room.is_private&&!memberRows.some(x=>x.user_id===sessionUser.id)){const joined=await db().rpc('join_chat_room',{p_room:id,p_password:null});if(!joined.error)memberRows=[...memberRows,{user_id:sessionUser.id}];}
  activeRoomManagers=new Set([room.owner_id,...(admins||[]).map(x=>x.user_id)]);const mutedUsers=new Set((moderations||[]).filter(x=>x.action==='mute').map(x=>x.user_id));const ids=[...new Set(memberRows.map(x=>x.user_id).concat((messages||[]).map(x=>x.sender_id)))];const {data:people}=ids.length?await db().from('profiles').select('id,display_name,username,avatar_url,vip_level').in('id',ids):{data:[]};const byId=Object.fromEntries((people||[]).map(x=>[x.id,x]));activeRoomOwnerId=room.owner_id;
  return page(room.name,'home',`<div class="room-page"><div class="room-head"><button class="btn ghost" onclick="location.hash='gathering'">العودة</button><button class="btn danger small" onclick="leaveRoom('${id}')">مغادرة</button><div><span class="eyebrow">${room.room_type==='game'?'غرفة لعبة':'تجمع ممتع'} · ${room.voice_enabled?'صوت وكتابة':'كتابة'}</span><h1>${escapeHtml(room.cover_emoji||'✨')} ${escapeHtml(room.name)}</h1></div><div class="room-tools"><button class="btn gold small" onclick="openRoomGamePicker('${id}')">🎮 ألعاب الغرفة</button><button class="btn ghost small" onclick="toggleRoomMembersDrawer('${id}')">👁 الأعضاء</button><button class="btn gold small" onclick="showGiftPicker('${id}')">🎁 هدية لشخص</button><button class="btn gold small" onclick="showMicGiftPicker('${id}')">🎙️ هدية للمايك</button><button class="btn gold small" onclick="showRoomWideGiftPicker('${id}')">👥 هدية للغرفة</button>${room.voice_enabled?`<button class="btn gold small" onclick="toggleVoiceRoom('${id}')">📞 دخول الصوت</button>`:''}</div></div>${room.voice_enabled?voiceSeatPanel(id):''}<div class="room-layout"><div class="panel room-chat"><div class="panel-head"><h2>دردشة الغرفة</h2><span>${messages?.length||0}</span></div><div class="chat-messages">${(messages||[]).map(m=>{const u=byId[m.sender_id]||{};return `<div class="room-message ${m.message_type==='game_system'?'game-system-message':''}" onclick="openUserProfile('${m.sender_id}')"><img class="room-avatar vip-avatar vip-${u.vip_level||0}" src="${u.avatar_url||DEFAULT_AVATAR}"><div><b>${escapeHtml(u.display_name||u.username||'مستخدم')}</b><small>${new Date(m.created_at).toLocaleTimeString('ar-EG',{hour:'2-digit',minute:'2-digit'})}</small><p>${roomMessageContent(m)}</p></div></div>`}).join('')||'<p class="empty">ابدأ المحادثة.</p>'}</div><div class="room-compose"><input id="room-message-input" placeholder="اكتب رسالة..." onkeydown="if(event.key==='Enter')sendRoomMessage('${id}')"><button class="btn ghost" onclick="toggleVoiceRecorder('${id}')">🎙️</button><button class="btn gold" onclick="sendRoomMessage('${id}')">إرسال</button></div></div><aside id="room-members-drawer-${id}" class="panel room-members room-members-drawer"><div class="panel-head"><h2>الأعضاء المتصلون</h2><button class="icon-btn" onclick="toggleRoomMembersDrawer('${id}')">×</button><span>${people?.length||0}</span></div>${(people||[]).map(u=>`<div class="room-member" onclick="openUserProfile('${u.id}')"><img class="room-avatar vip-avatar vip-${u.vip_level||0}" src="${u.avatar_url||DEFAULT_AVATAR}"><div><b>${escapeHtml(u.display_name||u.username)}</b><small>VIP ${u.vip_level||0}</small></div><button class="copy-id" onclick="event.stopPropagation();copyId('${u.id}')">نسخ</button>${activeRoomManagers.has(sessionUser.id)&&u.id!==sessionUser.id?`<button class="btn small ghost" onclick="event.stopPropagation();moderateRoomMember('${id}','${u.id}','${mutedUsers.has(u.id)?'unmute':'mute'}')">${mutedUsers.has(u.id)?'فك الكتم':'كتم'}</button><button class="btn small danger" onclick="event.stopPropagation();moderateRoomMember('${id}','${u.id}','kick')">طرد</button>`:''}${room.owner_id===sessionUser.id&&u.id!==sessionUser.id?`<button class="btn small ${admins?.some(a=>a.user_id===u.id)?'gold':'ghost'}" onclick="event.stopPropagation();setRoomAdmin('${id}','${u.id}',${!admins?.some(a=>a.user_id===u.id)})">${admins?.some(a=>a.user_id===u.id)?'إزالة المدير':'تعيين مدير'}</button>`:''}</div>`).join('')||'<p class="empty">لا يوجد أعضاء.</p>'}</aside></div></div>`);
}

let robotGameState=null;
function initRobotGame(game,bet){robotGameState={game,bet,turn:0,dice:null,pendingMove:null,players:[{name:'أنت',emoji:'🧑',pieces:[0,0,0,0],pos:0,color:'#67e8f9',human:true},{name:'Robot 1',emoji:'🤖',pieces:[0],pos:0,color:'#fb7185'},{name:'Robot 2',emoji:'🤖',pieces:[0],pos:0,color:'#a5b4fc'},{name:'Robot 3',emoji:'🤖',pieces:[0],pos:0,color:'#f7c948'},{name:'Robot 4',emoji:'🤖',pieces:[0],pos:0,color:'#86efac'}],winner:null};}
function robotRoll(){const s=robotGameState;if(!s||s.winner||s.turn!==0||s.pendingMove)return;const d=1+Math.floor(Math.random()*6);s.dice=d;if(s.game==='Ludo'){s.pendingMove=d;return renderRobotGame();}s.players[0].pos+=d;if(s.players[0].pos>=40)s.winner=s.players[0].name;s.turn=1;renderRobotGame();setTimeout(robotTurn,700);}
function moveHumanPiece(index){const s=robotGameState;if(!s||s.game!=='Ludo'||s.turn!==0||!s.pendingMove)return;const p=s.players[0];p.pieces[index]+=s.pendingMove;p.pos=Math.max(...p.pieces);if(p.pieces[index]>=40)s.winner=p.name;s.pendingMove=null;s.turn=s.winner?0:1;renderRobotGame();if(!s.winner)setTimeout(robotTurn,700);}
function robotTurn(){const s=robotGameState;if(!s||s.winner)return;const p=s.players[s.turn],d=1+Math.floor(Math.random()*6);s.dice=d;if(s.game==='Ludo'){const index=Math.floor(Math.random()*p.pieces.length);p.pieces[index]+=d;p.pos=Math.max(...p.pieces);if(p.pieces[index]>=40)s.winner=p.name;}else{p.pos+=d;if(p.pos>=40)s.winner=p.name;}s.turn=s.winner?0:(s.turn+1)%s.players.length;renderRobotGame();if(!s.winner&&s.turn!==0)setTimeout(robotTurn,700);}
function renderRobotGame(){const root=document.getElementById('robot-game-root');if(!root)return;const s=robotGameState;const board=Array.from({length:52},(_,i)=>{const tokens=[];s.players.forEach((p,pi)=>p.pieces.forEach((pos,si)=>{if(pos===i+1||(pos===0&&i===0))tokens.push(`<button class="ludo-token ${p.human&&s.pendingMove?'movable':''}" style="background:${p.color}" onclick="${p.human?'moveHumanPiece('+si+')':'return false'}" title="${p.name}">${p.emoji}</button>`)}));return `<div class="ludo-cell">${tokens.join('')}</div>`}).join('');const human=s.players[0];root.innerHTML=`<div class="game-topbar"><div><span class="eyebrow">مباراة Robot · تم خصم ${s.bet} كوينز</span><h1>${escapeHtml(s.game==='Ludo'?'Ludo Royale':s.game)}</h1></div><button class="btn ghost" onclick="location.hash='games'">الخروج</button></div><div class="robot-match-banner"><span>🤖</span><div><b>مباراة فعلية ضد 4 Robots</b><small>نسبة فوزك المحددة في هذه المباراة 30% · الرهان مدفوع</small></div><span class="status">${s.winner?'انتهت المباراة':s.turn===0?'دورك':'دور الروبوت'}</span></div>${s.game==='Ludo'?`<div class="ludo-layout"><div class="ludo-board real-ludo-board">${board}</div><aside class="panel ludo-side"><h2>اللاعبون والأحجار</h2>${s.players.map((p,i)=>`<div class="robot-player ${s.turn===i&&!s.winner?'active':''}"><span style="background:${p.color}">${p.emoji}</span><div><b>${p.name}</b><small>التقدم: ${p.pos}/40 · الأحجار: ${p.pieces.length}</small></div></div>`).join('')}<div class="dice-box">${s.dice||'—'}</div>${s.winner?`<h3 class="winner-text">الفائز: ${s.winner}</h3>`:s.pendingMove?`<p class="turn-hint">ظهرت ${s.pendingMove}. اضغط على الحجر الذي تريد تحريكه.</p>`:`<button class="btn gold full" onclick="robotRoll()" ${s.turn!==0?'disabled':''}>${s.turn===0?'ارمِ النرد':'انتظر دور الـRobot'}</button>`}<p class="empty">ارمِ النرد ثم اختر حجرًا مضيئًا على المسار لتحريكه.</p></aside></div>`:`<div class="panel generic-game"><div class="generic-arena">${s.players.map(p=>`<div class="arena-player" style="left:${Math.min(p.pos*2,90)}%;border-color:${p.color}"><span>${p.emoji}</span><b>${p.name}</b></div>`).join('')}</div><div class="generic-controls">${s.winner?`<h2>الفائز: ${s.winner}</h2>`:`<button class="btn gold" onclick="robotRoll()" ${s.turn!==0?'disabled':''}>${s.turn===0?'ابدأ الجولة':'الروبوت يلعب الآن'}</button>`}<p>المباراة بدأت بعد خصم الرهان: ${escapeHtml(s.game)} ضد Robots.</p></div></div>`}`;}
async function robotGamePage(game,bet){initRobotGame(decodeURIComponent(game),Number(bet));return `<main class="robot-game-shell"><div id="robot-game-root"></div></main>`;}
const roomGiftChannels={},roomGiftReady={};
function showRoomGiftBurst(payload={}){
  document.querySelector('.room-gift-burst')?.remove();
  const el=document.createElement('div'); el.className='room-gift-burst';
  const emoji=payload.emoji||'🎁', image=payload.image_url||'';
  el.innerHTML=`<div class="gift-route"><span>👤 ${escapeHtml(payload.sender_name||'发送者')}</span><b>🎁</b><span>👤 ${escapeHtml(payload.receiver_name||'接收者')}</span></div><div class="gift-explosion">${image?`<img src="${escapeHtml(image)}" alt="هدية">`:emoji}</div><strong>${escapeHtml(payload.gift_name||'هدية')}</strong><span>${escapeHtml(payload.sender_name||'مستخدم')} أرسلها إلى ${escapeHtml(payload.receiver_name||'عضو الغرفة')}</span><div class="gift-sparks">✦ ✧ ✺ ✧ ✦</div>`;
  document.body.appendChild(el); setTimeout(()=>el.remove(),3200);
}
function ensureRoomGiftChannel(roomId){
  if(!roomId||roomGiftChannels[roomId])return roomGiftChannels[roomId];
  const channel=db().channel('room-gifts-'+roomId);
  channel.on('broadcast',{event:'gift-sent'},({payload})=>showRoomGiftBurst(payload||{}));channel.on('broadcast',{event:'vip-entry'},({payload})=>{if(payload?.vip_level&&payload.room===roomId&&location.hash===`#room/${roomId}`)showVipEntryBurst(payload);});channel.on('broadcast',{event:'music-start'},({payload})=>playRoomMusic(payload||{}));channel.on('broadcast',{event:'music-stop'},()=>stopRoomMusic());
  roomGiftChannels[roomId]=channel;roomGiftReady[roomId]=new Promise(resolve=>channel.subscribe(status=>{if(status==='SUBSCRIBED')resolve(channel);}));return channel;
}
async function broadcastRoomEvent(roomId,event,payload){const channel=ensureRoomGiftChannel(roomId);if(!channel)return;try{await roomGiftReady[roomId];await channel.send({type:'broadcast',event,payload});}catch(e){console.warn('room event failed',e);}}
async function broadcastRoomGift(roomId,payload){
  const channel=ensureRoomGiftChannel(roomId); if(!channel)return;
  try{await roomGiftReady[roomId];await channel.send({type:'broadcast',event:'gift-sent',payload});}catch(e){console.warn('gift broadcast failed',e);}
}
let roomEntryPollTimer=null,roomEntryCursor=new Date().toISOString();
function stopRoomEntryPolling(){if(roomEntryPollTimer)clearInterval(roomEntryPollTimer);roomEntryPollTimer=null;}
function startRoomEntryPolling(roomId){stopRoomEntryPolling();roomEntryCursor=new Date().toISOString();const poll=async()=>{const {data:rows}=await db().from('messages').select('id,sender_id,created_at').eq('room_id',roomId).eq('message_type','vip_entry').gt('created_at',roomEntryCursor).order('created_at',{ascending:true}).limit(20);for(const row of rows||[]){roomEntryCursor=row.created_at;const {data:person}=await db().from('profiles').select('display_name,username,avatar_url,vip_level').eq('id',row.sender_id).maybeSingle();if(person?.vip_level&&location.hash===`#room/${roomId}`)showVipEntryBurst(person);}};poll();roomEntryPollTimer=setInterval(poll,1200);}
let activeRenderedRoute='';
async function render(){const ok=await requireAuth();if(!ok)return;const route=location.hash.slice(1)||'home';if(activeVoiceRoom&&activeRenderedRoute.startsWith('room/')&&activeRenderedRoute!==route){try{await toggleVoiceRoom(activeVoiceRoom.roomId);}catch(e){voiceStream?.getTracks().forEach(t=>t.stop());voiceStream=null;activeVoiceRoom=null;}}activeRenderedRoute=route;const map={home,games,gathering,profile:profilePage,vip:vipPage,top:topPage,search:searchPage,notifications,developer:developerPage};const view=route.startsWith('robot/')?()=>robotGamePage(...route.slice(6).split('/')):route.startsWith('room/')?()=>roomPage(route.slice(5)):route.startsWith('user/')?()=>userPage(route.slice(5)):route.startsWith('dm/')?()=>conversationPage(route.slice(3)):(map[route]||home);try{document.body.innerHTML=await view();if(route.startsWith('robot/'))renderRobotGame();if(!route.startsWith('room/'))stopRoomEntryPolling();if(route.startsWith('room/')){ensureRoomGiftChannel(route.slice(5));startRoomEntryPolling(route.slice(5));const savedVoice=JSON.parse(sessionStorage.getItem(VOICE_SESSION_KEY)||'null');if(savedVoice?.roomId===route.slice(5)&&!activeVoiceRoom)setTimeout(()=>toggleVoiceRoom(route.slice(5)),180);const vipEntry=JSON.parse(sessionStorage.getItem('webchat-vip-entry')||'null');if(vipEntry?.room===route.slice(5)){sessionStorage.removeItem('webchat-vip-entry');setTimeout(()=>showVipEntryBurst(vipEntry),120);}}document.title='WebChat · '+route;}catch(e){console.error(e);document.body.innerHTML=`<main class="page-content"><div class="panel"><h2>تعذر تحميل الصفحة</h2><p class="empty">${escapeHtml(e.message)}</p></div></main>`;}}
if(location.pathname.endsWith('app.html')){addEventListener('hashchange',render);addEventListener('DOMContentLoaded',render);}

window.addEventListener('pagehide',()=>{try{voiceStream?.getTracks().forEach(t=>t.stop());Object.values(voicePeers||{}).forEach(pc=>pc.close());}catch(e){}});
